var ZAIKA_EXTRA_RU={"biryani":{"intro":"Biryani wo khana hai jo aksar mehmanon aur khushi ke mauqon par banti hai, aur Karachi style apne tez masale, alag alag chawal aur dum ki khushbu ke liye mashhoor hai jo dhakkan uthne se pehle poore ghar mein phail jati hai. Neeche diya tareeqa chicken ko juicy aur chawal ko khushbudar rakhta hai, aur tehon ko ek naram mass nahi banne deta. Marination hi asal zaiqa banati hai, is liye pakana zyada tar teh lagana aur intezar karna hai. Isay degchi se seedha serve karein, raita aur salad ke sath, jab tak bhaap nikal rahi ho.","ing":["Chicken 750g","dahi 1 cup","Basmati chawal 3 cup (bhigoye hue)","Biryani masala 3 tbsp","adrak lehsan paste 2 tbsp","Piyaz 3 (brown ki hui)","Tamatar 2","hari mirch 4","Hara dhaniya","podina","lemon","Zafran / food colour","ghee 3 tbsp","Namak","tez patta","ilaichi","laung (chawal ke paani ke liye)"],"steps":["Chawal ko saaf paani aane tak dho kar 30 minute bhigo dein, phir chaan lein. Dahi, biryani masala, adrak lehsan paste aur namak chicken mein mila kar 30 minute marinate karein.","Ek bare bartan mein namak aur sabut masalon ke sath paani ubalein. Chawal daal kar 70 percent tak pakayein, beech mein sakht rahe, phir foran chaan lein.","Ghee garam kar ke piyaz ko gehra sunehra hone tak brown karein, aadhi teh lagane ke liye nikaal lein, baqi pan mein rehne dein.","Tamatar aur marinated chicken daal kar darmiyani tez aanch par 10 se 12 minute bhunein, jab tak masala gaarha ho jaye aur tail alag nazar aaye.","Chicken masala ek bhari degchi mein phaila dein. Aadhe chawal daalein, phir dhaniya, podina, brown piyaz, lemon aur zafran chhidkein.","Baqi chawal daalein, upar baqi piyaz, herbs aur zafran aur ek chamach ghee daalein. Dhakkan ko kapde ya foil se band karein.","Halki aanch par 20 minute dum dein, dhakkan na kholein, phir aanch se utaar kar 10 minute rest dein.","Dhakkan kholein, kaante se kinaron se halke haath se phulaein, halka milayein taake rang nazar aate rahein, aur garam serve karein."],"tip":"Chawal zyada na ubalein. Wo dum par pak jayenge. Dum par dhakkan par kapda rakhein taake bhaap bahar na nikle, aur chawal ka paani chakhein. Wo halka namkeen hona chahiye, kyunke saada chawal ko is namak ki zaroorat hoti hai.","notes":["Haddi wala chicken dum par zyada juicy rehta hai. Leg pieces lein aur zyada charbi hata dein.","Purani basmati ke daane alag rehte hain. Nayi chawal jaldi naram ho jati hai, is liye ubalne ka waqt dekhein.","Full fat dahi marinade ko chicken par chipka deti hai. Low fat dahi garam hone par phat sakti hai.","Biryani masala har brand ka mukhtalif hota hai. Zyada mirch daalne se pehle masala chakhein, aur agli dafa adjust karein."],"variations":["Sabzi biryani: chicken ki jagah aloo, phool gobhi, matar aur gajar lein, sabziyon ko halka marinate karein, aur dum 15 minute kar dein.","Mutton biryani: 750g mutton lein, teh lagane se pehle masala itna pakayein ke gosht taqreeban gal jaye, aur 30 minute dum dein.","Kam mirch wali: hari mirch aadhi kar dein, zyada laal mirch na daalein, aur zyada raita ke sath serve karein."],"serving":"4 logon ke liye raita, kachumber salad aur lemon ke sath kaafi hai. Degchi table ke beech mein rakhein aur wahin kholein, taake sab ko dum ki khushbu mile. Naan zaroori nahi, kyunke chawal hi asal khana hai. Lassi ya podine ka drink mirch ko balance karta hai.","storage":"1 ghante ke andar thanda kar ke airtight dabbe mein fridge mein 2 din tak rakhein. Dhaki hui kadhai mein halki aanch par 2 tbsp paani ke sath dobara garam karein, ya microwave mein dhak kar garam karein, jab tak poori tarah bhaap na nikle. Ek dafa se zyada dobara garam na karein. Hisson mein freeze kar ke 1 mahine tak rakhein, aur garam karne se pehle fridge mein raat bhar thaw karein.","mistakes":["Dum se pehle chawal poora ubaal lena. Wo degchi mein naram ho jata hai.","Dum ke doran dhakkan kholna. Bhaap nikal jati hai aur chawal kacha reh jata hai.","Chawal ke paani mein namak kam rakhna. Tehein pheeki lagti hain.","Dum ke baad zor se hilana. Daane toot jate hain aur rang ek ho jate hain."],"faq":[["Kya biryani zafran ke baghair ban sakti hai?","Ji haan. Garam doodh mein ghula hua aik chutki peela food colour use karein, ya chor dein. Zaiqa masale aur dum se aata hai, sirf rang se nahi."],["Chicken ko kitni der marinate karna chahiye?","Kam az kam 30 minute. Fridge mein 2 se 4 ghante behtar hai. Isay fridge mein rakhein, aur marinated chicken ko room temperature par na chhodein."],["Mere chawal chipke hue kyun bante hain?","Chawal zyada ubal gaya tha, ya foran chhana nahi gaya, ya degchi zor se hilayi gayi. 70 percent par chhanein aur phulane se pehle rest dein."],["Kya boneless chicken use kar sakte hain?","Ji haan. Thigh pieces lein aur masala pakane ka waqt 3 se 4 minute kam kar dein, taake chicken khushk na ho."]]},"nihari":{"intro":"Nihari asal mein sabr ka khana hai, weekend ka salan jo sabr ka inaam naram gosht aur chamach par chipakne wali gravy ki surat mein deta hai. Is version mein beef shank taqreeban 2 ghante halki aanch par pakta hai, jab tak gosht haddi se alag na ho jaye aur masala gehra rang aur zaiqa na le le. Aakhir mein atta ka ghol hi nihari ki mashhoor gaarhi, chamkili gravy banata hai, is liye isay ahista daalna aur achhi tarah hilana zaroori hai. Isay taazi naan aur classic garnish ke sath ubalta hua serve karein, aur table par extra lemon rakhein.","ing":["Beef (shank) 1 kg","Nihari masala 4 tbsp","atta 3 tbsp","Adrak lehsan paste 2 tbsp","piyaz 1","Ghee / tail 1/2 cup","Adrak","hari mirch","lemon (garnish ke liye)","Hara dhaniya"],"steps":["Ghee garam karein, kati hui piyaz ko jalaye baghair halka brown karein, adrak lehsan paste daalein, aur kachi khushbu jane tak 1 minute bhunein.","Gosht aur nihari masala daal kar darmiyani tez aanch par 8 se 10 minute bhunein, jab tak gosht ka rang badal jaye aur masala har tukde par lag jaye.","Itna garam paani daalein ke gosht se taqreeban 2 inch upar ho, ubal layein, aur upar aane wali jhaag hata dein.","Bartan dhak kar halki aanch par 2 ghante pakayein. Beech beech mein hilayein, aur paani gosht se neeche jaye to garam paani daalein.","Gosht check karein. Wo kaante se alag hona chahiye aur haddi se asani se chhootna chahiye. Agar sakht ho to 20 se 30 minute aur pakayein.","Atte ko 1 cup thande paani mein mila kar bilkul hamwar kar lein, koi gutli na rahe. Bartan hilate hue patli dhaar mein daalein.","10 se 15 minute halki aanch par hilate hue pakayein, jab tak gravy gaarhi aur chamkili ho jaye aur chamach ke peeche chipak jaye.","10 minute rest dein, namak chakhein, aur naan ke sath serve karein, upar adrak, hari mirch, lemon aur dhaniya daal kar."],"tip":"Gravy patli na rakhein. Nihari apni gaarhi, chamkili gravy se pehchani jati hai. Atta ahista daalein taake gutliyan na banein, aur daalte waqt lagatar hilayein.","notes":["Shank, haddi aur connective tissue ke sath, nihari ke liye behtareen hai. Is se gravy mein body aati hai. Boneless stewing beef bhi chal jata hai, lekin gravy utni rich nahi hoti.","Nihari masala har brand mein tez ya halka hota hai. Pehli dafa di hui miqdar use karein, aur agli dafa adjust karein.","Ghee se riwayati zaiqa aata hai. Tail bhi chal jata hai, aur aadha ghee aadha tail behtareen darmiyana rasta hai.","Atta sirf gaarha karne ke liye hai. Zyada na daalein, kyunke is se masale ka zaiqa halka ho jata hai."],"variations":["Mutton nihari: wahi tareeqa use karein aur taqreeban 1 ghanta 30 minute pakayein, pehle check karein, kyunke mutton jaldi gal jata hai.","Chicken nihari: haddi wala chicken lein, 35 se 40 minute pakayein, atte ka ghol jaldi daalein, aur halki gravy ki umeed rakhein.","Zyada mirch wali: zyada hari mirch pakate waqt nahi, serve karte waqt daalein, taake mirch taazi lage."],"serving":"5 logon ke liye naan aur table par garnish ke chhote bowls ke sath kaafi hai, taake har shakhs apne zaiqe ke mutabiq adrak, mirch, lemon aur dhaniya daal sake. Nihari riwayati tor par nashtay ya weekend ke lunch mein gehre bowls mein serve hoti hai, gosht par khoob gravy daal kar. Naan garam rakhein aur bartan table par tab layein jab wo ubal raha ho.","storage":"Thanda kar ke airtight dabbe mein fridge mein 3 din tak rakhein. Thanda hone par gravy gaarhi ho jati hai. Halki aanch par thoda garam paani daal kar ahista garam karein, hilate hue, jab tak poori tarah bhaap na nikle. 2 mahine tak freeze karein, fridge mein raat bhar thaw karein, aur garnish sirf serve karte waqt taazi daalein.","mistakes":["Tez aanch par pakana. Gosht sakht ho jata hai aur gravy jaldi kam ho jati hai.","Atta khushk ya aik hi dafa daalna. Gutliyan ban jati hain aur asani se nahi nikalti.","Pakane ka waqt kam rakhna. Gosht haddi se alag hone ke bajaye chewy rehta hai.","Thandi naan aur garnish ke baghair serve karna. In ke baghair zaiqa pheeka lagta hai."],"faq":[["Meri nihari ki gravy patli kyun hai?","Atta kam tha, ya daalne ke baad simmer kam waqt hua. Hilate hue 10 se 15 minute simmer karein. Zaroorat ho to paani mein ghula hua 1 extra tbsp atta daalein."],["Kya pressure cooker use kar sakte hain?","Ji haan. Pressure aane ke baad gosht aur masala 25 se 30 minute pakayein, phir khule bartan mein atte ke ghol ke sath mukammal karein. Safety ke liye apne cooker ki instructions follow karein."],["Kya nihari bohat mirch wali hoti hai?","Masala garmahat deta hai, jalan nahi. Serve karte waqt taazi mirch se har shakhs apni marzi se tez kar sakta hai."],["Kya isay aik din pehle bana sakte hain?","Ji haan. Fridge mein raat bhar zaiqa behtar ho jata hai. Ahista garam karein, zyada gaarhi ho to thoda garam paani daalein, aur garnish taazi daalein."]]},"karahi":{"intro":"Chicken karahi dhabe ka behtareen khana hai, gehri kadhai mein jaldi pakne wala, baghair piyaz aur baghair masalon ki lambi list ke. Taaze tamatar masala ban jate hain, adrak aur hari mirch aakhir mein daali jati hain, aur poora khana taqreeban 40 minute mein tayyar ho jata hai. Raaz aanch aur timing hai. Aanch tez rakhein, tamatar ko apna kaam karne dein, aur adrak tab daalein jab karahi ubal rahi ho. Isay kadhai se seedha garam roti ya naan ke sath khayein, jab masala chamkila ho aur chicken naram ho.","ing":["Chicken 750g","tamatar 4 bare","Adrak lehsan paste 1 tbsp","Hari mirch 4","adrak julienne","Ghee / tail 1/2 cup","Namak","kuti hui laal mirch","garam masala","Hara dhaniya"],"steps":["Tamatar ko 4 tukdon mein kaatein aur adrak, mirch aur dhaniya tayyar rakhein. Karahi jaldi banti hai, is liye sab kuch haath ke paas hona chahiye.","Kadhai mein ghee tez aanch par garam karein. Chicken daal kar 4 se 5 minute fry karein, baar baar palat kar, jab tak bahar ka rang badal jaye.","Adrak lehsan paste daal kar 1 minute bhunein. Tamatar aur thoda namak daal kar dhak dein, aur darmiyani tez aanch par 8 se 10 minute pakayein.","Dhakkan hata kar naram tamatar ko chamach ke peeche se mash karein. Bhunte rahein jab tak masala gaarha ho jaye aur tail upar aa jaye.","Kuti hui laal mirch daalein aur namak chakhein. Agar masala khushk lage to sirf 2 tbsp garam paani daalein, zyada nahi.","Aadhi adrak julienne aur 2 kati hui hari mirch daalein. 2 minute aur bhunein taake in ka zaiqa masale mein chala jaye.","Garam masala chhidkein, dhak dein, aur halki aanch par 5 minute dum dein. Chicken andar tak pak jana chahiye aur juicy rehna chahiye.","Baqi adrak, mirch aur taaza dhaniya daalein. Foran serve karein, kadhai se seedha, roti ya naan ke sath."],"tip":"Karahi mein paani na daalein. Tamatar ka apna paani kaafi hai. Aanch tez rakhein taake chicken naram rahe aur masala achha bhune, aur taazi adrak aakhir mein daalein, shuru mein nahi.","notes":["Pake hue, naram tamatar lein. Sakht tamatar der se ghulte hain aur masala paani wala reh jata hai.","Haddi wala chicken zyada zaiqa deta hai aur juicy rehta hai. Boneless thigh bhi chal jata hai, lekin 3 se 4 minute kam pakayein.","Ghee se dhabe ka zaiqa aata hai. Tail bhi chal jata hai, lekin aakhir mein thodi zyada adrak daalein.","Taazi adrak julienne garnish bhi hai aur zaiqa bhi. Sukhi adrak powder is ki jagah nahi le sakti."],"variations":["Mutton karahi: 750g mutton lein, dhak kar 40 se 50 minute naram hone tak pakayein, phir masala hamesha ki tarah tez aanch par bhunein.","Hari mirch karahi: laal mirch chor dein, 8 hari mirch lein, aadhi masale mein aur aadhi garnish mein, taaze tez zaiqe ke liye.","Butter karahi: aanch se utaar kar 1 tbsp makhan aur 2 tbsp cream mila dein, zyada rich aur halki version ke liye."],"serving":"4 logon ke liye roti ya naan, piyaz aur lemon ki saada salad, aur pasand ho to raita ke sath kaafi hai. Kadhai mein hi serve karein, lemon ke sath, aur garam garam khayein. Masala roti se uthane ke liye hota hai, is liye zyada roti tayyar rakhein. Thanda drink ya lassi mirch mein madad karta hai.","storage":"1 ghante ke andar thanda kar ke airtight dabbe mein fridge mein 2 din tak rakhein. Kadhai mein darmiyani aanch par dhak kar 1 se 2 tbsp paani ke sath dobara garam karein, jab tak bhaap na nikle. Dobara garam karne ke baad taazi adrak aur dhaniya daalein. 1 mahine tak freeze kar sakte hain, lekin thaw hone par tamatar masala naram ho jata hai, is liye taaza behtareen hai.","mistakes":["Shuru mein paani daalna. Masala gaarhi chamkili karahi ke bajaye patli curry ban jata hai.","Poora waqt halki aanch par pakana. Chicken bhaap mein pak jata hai, tamatar tukdon mein rehte hain, aur masala theek se nahi bhunta.","Adrak sirf shuru mein daalna. Wo pak kar khatam ho jati hai, aur taaza finish nahi milta.","Boneless chicken ko zyada pakana. Tez aanch par wo jaldi khushk ho jata hai, is liye jaldi check karein."],"faq":[["Meri karahi mein masala kyun nahi hai?","Tamatar achhi tarah mash aur bhune nahi gaye, ya paani daal diya gaya. Tamatar achhi tarah mash karein aur tail alag hone tak bhunein."],["Kya karahi kadhai ke baghair ban sakti hai?","Ji haan. Gehri, bhari wok ya frying pan use karein. Patli pan masala jala deti hai, is liye aanch thodi kam rakhein aur zyada hilayein."],["Kya karahi mein piyaz hoti hai?","Riwayati Pakistani karahi mein piyaz nahi hoti. Tamatar ka paani masala banata hai. Piyaz se mukhtalif khana banta hai, curry ke qareeb."],["Chicken pak gaya hai, kaise pata chalega?","Sab se mote tukde ko kaatne par ras saaf nikle, aur gosht gulabi na rahe. Shak ho to sab se bara tukda kaat kar check karein."]]},"daal":{"intro":"Daal fry roz ka wo khana hai jo sabit karta hai ke saada khana bhi yaadgar ho sakta hai, bas daal naram pakni chahiye aur tadka garam garam daal kar foran dhak dena chahiye. Masoor aur moong jaldi pak jati hain aur baghair cream ke creamy ho jati hain, aur upar ghee, lehsan, zeera aur sabut laal mirch ki khushbu bowl se pehle table tak pahunchti hai. Ye chawal ya roti ke sath sukoon ka khana hai, busy hafton aur un dinon ke liye jab kuch khaas nahi chahiye. Poori recipe taqreeban 35 minute leti hai, aur zyada waqt daal khamoshi se ubalti hai.","ing":["Masoor / moong daal 1½ cup","Haldi 1/2 tsp","namak","Lehsan 4 jawey","zeera 1 tsp","Sabut laal mirch 3","ghee 3 tbsp","Hari mirch","hara dhaniya","lemon"],"steps":["Daal ko kai dafa paani badal kar dhoyein, jab tak paani taqreeban saaf na ho jaye, phir achhi tarah chaan lein.","Daal ko bartan mein haldi aur 4 cup paani ke sath rakhein. Ubal layein, jhaag hata dein, aur aanch halki kar dein.","20 se 25 minute halki aanch par pakayein, beech beech mein hilate hue, jab tak daal bilkul naram aur creamy na ho jaye. Zyada gaarhi ho to garam paani daalein.","Chakhein aur namak daalein. Daal behne wali honi chahiye, sakht nahi, kyunke thanda hone par gaarhi ho jati hai.","Lehsan ko patla kaatein. Chhoti kadhai mein ghee darmiyani aanch par garam karein aur zeera daalein. Jab chatakne lage to lehsan daalein.","Lehsan ko sunehra hone tak fry karein, brown nahi. Sabut laal mirch daalein, das tak ginein, aur kadhai foran aanch se utaar lein.","Garam tadka aik hi dafa daal par daalein, sizzle sunein, aur 2 minute ke liye bartan dhak dein taake khushbu andar rahe.","Hari mirch aur dhaniya milayein, upar lemon nichodein, aur chawal ya roti ke sath garam serve karein."],"tip":"Jaise hi tadka daalein, daal ko dhak dein. Is se khushbu daal ke andar rehti hai, kitchen mein nahi nikalti, aur lehsan ka zaiqa poore bartan mein phail jata hai.","notes":["Masoor daal sab se jaldi pakti hai aur creamy hoti hai. Moong daal thodi shape rakhti hai. Dono chal jati hain, aur aadhi aadhi mix bhi achhi hai.","Haldi rang aur halke zaiqe ke liye hai. Zyada daalne se daal karwi ho jati hai, is liye naap kar daalein.","Tadke ke liye lehsan ko kaatein, kootain nahi. Qashain aik jaisi sunehri hoti hain aur kurkuri rehti hain.","Ghee tadke ka zaiqa sab se achha uthata hai. Tail bhi chal jata hai, lekin aik extra lehsan ka jawa daalein."],"variations":["Palak daal: paki hui daal mein 2 cup kata hua palak mila kar tadke se pehle 5 minute simmer karein.","Tamatar daal: shuru mein daal ke sath 1 kata hua tamatar daalein, khatte aur thode gaarhe result ke liye.","Zyada lehsan wali: tadke mein lehsan dugna kar dein aur aadha tsp kuti hui laal mirch bhi daalein."],"serving":"4 logon ke liye ubale hue chawal ya roti, lemon ka tukda, aur side par saada salad ya achar ke sath kaafi hai. Daal gehre bowls mein patli aur garam serve karni chahiye, tadka upar nazar aana chahiye. Chawal ke sath serve karein to daal table par chawal par daalein. Tala hua anda ya papad isay poora khana bana deta hai.","storage":"Thanda kar ke airtight dabbe mein fridge mein 3 din tak rakhein. Fridge mein daal gaarhi ho jati hai, is liye dobara garam karte waqt thoda garam paani mila kar hilayein. Halki aanch par hilate hue garam karein, jab tak bhaap na nikle, aur dobara garam karne ke baad taaza dhaniya daalein. Hisson mein 1 mahine tak freeze karein, fridge mein thaw karein, aur behtareen khushbu ke liye taaza tadka banayein.","mistakes":["Daal ko kam pakana. Daane wali daal tadka kitna bhi achha ho, creamy nahi hoti.","Lehsan jalana. Brown lehsan karwa ho jata hai aur poora bartan kharab kar deta hai, is liye kadhai jaldi utaar lein.","Tadke ke baad bartan khula chhodna. Khushbu nikal jati hai aur daal pheeki lagti hai.","Daal sakht rehne par namak shuru mein daalna, is se naram hone mein der ho sakti hai, is liye naram hone ke baad namak daalein."],"faq":[["Tadka daal ke liye sab se achhi daal kaun si hai?","Masoor sab se jaldi aur creamy hoti hai. Moong qareeb dosri hai. Toor daal bhi chal jati hai, lekin isay zyada waqt chahiye aur pressure cooker madad karta hai."],["Kya daal fry ghee ke baghair ban sakti hai?","Ji haan. Tail use karein aur aik extra lehsan ka jawa daalein. Result halka hota hai, aur tadka phir bhi kaam karta hai, lekin khushbu utni rich nahi hoti."],["Meri daal paani wali kyun hai?","Isay kaafi der simmer nahi kiya gaya, ya paani zyada use hua. Kuch minute baghair dhak ke simmer kar ke gaarha karein, aur yaad rakhein ke thanda hone par aur gaarhi hoti hai."],["Kya daal pressure cooker mein paka sakte hain?","Ji haan. 2 seeti ya taqreeban 8 minute pressure par pakayein, pressure khud khatam hone dein, phir khule bartan mein tadka laga kar mukammal karein."]]},"chapli":{"intro":"Chapli kabab Peshawar hai aik plate mein, chapta, naram, masaledar, aur tawe par tala hua jab tak kinare kurkure na ho jayein. Is ka naam is ki chapti shape se aaya hai, aur zaiqa tamatar, anar dana, kute hue sabut dhaniya aur hari mirch se aata hai jo qeeme mein milaye jate hain. Ye street food bhi hai aur dawat ka khana bhi, naan, piyaz aur hari chutney ke sath khaya jata hai, aur thande qeeme aur naram haathon se behtareen banta hai. Isay darmiyani halki aanch par fry karein taake beech mein pak jaye aur bahar na jale, aur beech mein tamatar ka tukda dabayein, jaise kabab banane wale karte hain.","ing":["Beef qeema 500g","Tamatar 1 bareek kata","piyaz 1","Anar dana 1 tbsp","kuta hua sabut dhaniya","Hari mirch 3","adrak","namak","Makai ka atta 2 tbsp","Talne ke liye tail"],"steps":["Piyaz aur tamatar ko bohat bareek kaatein aur tamatar ka zyada ras nichod dein, taake mix shape dene ke liye sakht rahe.","Qeema aik bowl mein tamatar, piyaz, anar dana, kuta dhaniya, mirch, adrak, namak aur makai ke atte ke sath rakhein. Haathon se sirf milne tak milayein.","Dhak kar mix ko fridge mein 20 minute rest dein. Thanda qeema shape achhi rakhta hai aur behtar fry hota hai.","Haathon ko thande paani se geela karein. Aik hissa lein, taqreeban 4 inch ki patli gol tikki banayein, aur beech mein tamatar ka chhota tukda dabayein.","Tawe par tail ki achhi teh darmiyani aanch par garam karein. Tail itna garam ho ke sizzle kare, lekin dhuan na nikle.","Kabab ko jagah chhod kar tawe par rakhein. Pehli taraf 4 se 5 minute fry karein, baghair dabaye.","Chaudi spatula se ahista paltein aur 4 se 5 minute aur fry karein, jab tak dono taraf sunehre aur andar tak pak na jayein.","Nikaal kar halka drain karein, aur hari chutney, kati hui piyaz aur naan ke sath garam serve karein."],"tip":"Kabab ko zyada na dabayein. Ahista paltein warna toot jayenge. Thanda qeema behtar kabab banata hai, is liye mix ko har batch shape dene tak fridge mein rakhein.","notes":["Thodi charbi wala qeema lein, taqreeban 15 se 20 percent. Bilkul lean qeema khushk aur tootne wala kabab banata hai.","Makai ka atta mix ko bandhta hai aur classic texture deta hai. Gehun ka atta bhi chal jata hai, lekin kabab ghana hota hai.","Anar dana khatta pop deta hai. Isay halka koot lein, paste na banayein.","Bareek kata tamatar nami aur zaiqa deta hai, lekin zyada ras kabab ko tod deta hai, is liye pehle drain karein."],"variations":["Chicken chapli: chicken qeema lein, 1 extra tbsp makai ka atta daalein, aur har taraf 3 se 4 minute fry karein, kyunke chicken jaldi pak jata hai.","Zyada mirch wali: 1 tsp kuti hui laal mirch aur aik extra hari mirch daalein, aur zyada chutney ke sath serve karein.","Chapli burger: kabab ko sekay hue bun mein piyaz, tamatar, chutney aur tale hue ande ke sath rakhein, Peshawar style burger ke liye."],"serving":"4 logon ke liye naan, hari chutney, kati hui piyaz, lemon aur salad ke sath main dish ke tor par kaafi hai. Har shakhs ko 2 kabab khoob chutney ke sath dein, aur zyada naan garam rakhein. Chapli kabab starter ke tor par bhi achha hai, main course se pehle har shakhs ko aik kabab chutney aur lemon ke sath. Podine ka raita mirch ko thanda karta hai.","storage":"Thanda kar ke pake hue kabab airtight dabbe mein fridge mein 2 din tak rakhein. Tawe par darmiyani aanch par garam karein jab tak andar tak garam na ho jaye, ya oven mein 180C par 8 se 10 minute. Kacha mix fridge mein 1 din tak rehta hai. Shape diye hue kache kabab ko baking paper ke beech mein rakh kar 1 mahine tak freeze karein, aur frozen hi fry karein, har taraf 2 minute zyada dein.","mistakes":["Mote kabab banana. Bahar jal jata hai aur beech mein kacha reh jata hai, is liye patle aur aik jaise rakhein.","Bohat tez aanch par fry karna. Masale jal jate hain aur kabab palatne par toot jata hai.","Spatula se dabana. Is se ras nikal jata hai aur kabab khushk ho jata hai.","Dukan se laya garam qeema use karna. Wo naram aur chipchipa hota hai aur shape dena mushkil hota hai, is liye pehle thanda karein."],"faq":[["Mere chapli kabab kyun toot jate hain?","Mix zyada geela tha, kabab mota tha, ya jaldi palat diya gaya. Tamatar drain karein, mix thanda karein, kabab patle rakhein, aur pehli taraf set hone dein phir paltein."],["Kya chapli kabab bake kar sakte hain?","Ji haan. Tail brush kar ke 200C par 15 se 18 minute bake karein, aik dafa palat kar. Wo tale hue kabab jitne kurkure nahi hote, lekin phir bhi mazedar hote hain."],["Anar dana kis liye hota hai?","Anar dana khatta, fruity zaiqa deta hai jo rich qeeme ko balance karta hai. Na mile to 1 tsp lemon ras aur kuch kuti hui khushk cranberry use karein, lekin zaiqa mukhtalif hota hai."],["Kya mix pehle se bana sakte hain?","Ji haan. Mila kar dhak kar fridge mein 1 din tak rakhein. Fry karne se pehle hi shape dein, taake kabab apni form rakhein."]]},"tikka":{"intro":"Chicken tikka wo khana hai jo achhe tareeqe se sabr sikhata hai. Marinade kaam karti hai, dahi aur masale kam az kam aik ghante tak gosht mein jate hain, aur grill ko sirf tez aanch aur har taraf kuch minute chahiye. Theek bane to bahar halka charred aur smoky hota hai, andar juicy rehta hai, aur aakhir mein lemon aur chaat masala sab kuch jaga deta hai. Ye starter, naan ke sath main dish, aur agle din wraps aur salad mein kata hua, sab mein chal jata hai. Neeche di recipe oven grill ya barbecue ke liye hai, aur garam pan bhi chal jata hai agar wahi ho.","ing":["Chicken (leg / boneless) 750g","Dahi 1/2 cup","laal mirch 1 tbsp","Haldi","garam masala","zeera powder","Adrak lehsan paste 1 tbsp","lemon 1 (Tail / makhan brush karne ke liye)"],"steps":["Chicken ko aik jaise tukdon mein kaatein aur har tukde par 2 halke cut lagayein, taake marinade andar tak jaye.","Dahi, laal mirch, haldi, garam masala, zeera powder, adrak lehsan paste, lemon ras aur namak ko hamwar paste bana lein.","Chicken par achhi tarah lagayein, dhak kar fridge mein kam az kam 1 ghanta rakhein. Raat bhar bhi theek hai aur zaiqa gehra hota hai.","Pakane se 20 minute pehle chicken nikaal lein, taake aanch par jate waqt fridge jitna thanda na ho.","Grill ya barbecue ko tez garam karein. Rack par halka tail lagayein aur chicken ko aik teh mein jagah chhod kar rakhein.","Pehli taraf 6 se 8 minute grill karein, aik dafa makhan ya tail brush kar ke, jab tak kinare halke charred na ho jayein.","Palat kar 6 se 8 minute aur grill karein, jab tak andar tak pak jaye aur ras saaf nikle.","5 minute rest dein, lemon ras aur chaat masala chhidkein, aur piyaz, chutney aur naan ke sath garam serve karein."],"tip":"Marination jitni lambi, tikka utna naram. Waqt kam ho to kam az kam 30 minute zaroor dein, aur scoring kabhi na chhodein, kyunke isi se marinade mote tukdon mein jati hai.","notes":["Thigh ka gosht tez aanch par breast se zyada juicy rehta hai. Breast bhi chal jata hai, lekin aik minute pehle check karein.","Dahi ko latka lein ya gaarhi dahi use karein. Paani wali dahi chicken se phisal jati hai aur grill par jal jati hai.","Marinade mein taaza lemon naram karne mein madad karta hai, lekin zyada der zyada lemon surface ko mushy bana sakta hai, is liye raat bhar wali marinade mein lemon halka rakhein.","Chaat masala aakhir mein daalein, marinade mein nahi, taake is ki khattapan taaza rahe."],"variations":["Malai tikka: laal mirch ki jagah safed mirch lein, marinade mein 2 tbsp cream aur 1 tbsp cheese daalein, halki creamy version ke liye.","Hariyali tikka: dhaniya, podina, hari mirch aur dahi ko blend kar ke hari marinade banayein, aur wahi tareeqe se grill karein.","Tikka wraps: bacha hua tikka kaat kar parathe ya roti mein piyaz, chutney aur salad ke sath roll karein, agle din ke lunch ke liye."],"serving":"4 logon ke liye naan ya roti, kati hui piyaz, lemon, hari chutney aur salad ke sath kaafi hai. Garam platter par grill se seedha serve karein, table par lemon nichod kar. Tikka chawal par, wrap mein, ya salad par bhi achha lagta hai. Side par zyada chutney rakhein, kyunke log hamesha aur mangte hain.","storage":"Thanda kar ke airtight dabbe mein fridge mein 2 din tak rakhein. 180C par garam oven mein 8 minute, ya pan mein darmiyani aanch par garam karein, jab tak bhaap na nikle. Microwave mein zyada der garam na karein, kyunke chicken khushk ho jata hai aur char naram ho jata hai. Marinated kacha chicken fridge mein 1 din tak rehta hai. Paka hua tikka 1 mahine tak freeze karein aur fridge mein thaw karein.","mistakes":["Fridge se thanda chicken grill karna. Bahar jal jata hai aur andar kacha reh jata hai, is liye pehle room temperature par layein.","Grill par bheed karna. Tukde charred hone ke bajaye bhaap mein pak jate hain, is liye jagah chhodein aur zaroorat ho to batches mein pakayein.","Rest na dena. Foran kaatne se ras nikal jata hai aur tikka khushk ho jata hai.","Patli marinade use karna. Wo tapak jati hai aur jal jati hai, chicken pheeka reh jata hai."],"faq":[["Kya tikka pan mein paka sakte hain?","Ji haan. Bhari pan mein tez aanch par thode tail ke sath har taraf 6 se 7 minute pakayein. Smoky char waisa nahi hoga, lekin zaiqa qareeb hoga."],["Ghar par smoky zaiqa kaise layein?","Grill karne ke baad bartan mein garam koylay ke tukde ke sath chhota steel bowl rakhein, us par tail ke chand drops daalein, 2 minute dhak dein, aur bowl nikaal lein. Kitchen mein hawa ka guzar rakhein."],["Kya breast chicken use kar sakte hain?","Ji haan, lekin zyada na pakayein. Har taraf 5 se 6 minute ke baad check karein, aur achhi tarah rest dein. Thigh zyada maaf karne wala hai."],["Kya tikka mirch wala hota hai?","Ye garam aur masaledar hota hai, bohat tez nahi. Halki version ke liye laal mirch 1 tsp kar dein, aur chutney table par mirch de degi."]]},"halwapuri":{"intro":"Halwa puri Lahore mein Itwaar ka nashta hai, aur kai gharon mein ye sirf khana nahi, poora event hai. Teen cheezein ikathi aati hain, phuli hui puri, naram suji ka halwa, aur aloo ke sath masaledar chanay, aur maza aik niwale mein teeno lene mein hai. Har hissa apne tor par saada hai, lekin timing ahm hai. Puri aakhir mein fry karein, taake phuli hui aur garam aaye, halwa garam aur naram rakhein, aur chanon ko itna simmer karein ke masala un par lag jaye. Isay aik slow subah pakayein, ikathe khayein, aur jaldi na karein.","ing":["Maida 2 cup","suji 1 cup","Cheeni 1 cup","ghee 1/2 cup","Chane (uble hue) 2 cup","Aloo 1","piyaz","tamatar","Garam masala","haldi","laal mirch","Ilaichi (badam garnish ke liye)"],"steps":["Maide ko paani aur chutki bhar namak ke sath sakht, hamwar atta gundhein. Dhak kar 20 minute rest dein.","Agar chane uble hue nahi hain to ubal lein, jab tak naram ho jayein lekin mushy na hon, aur in ke pakane ka 1 cup paani bacha lein.","Suji ko halki aanch par ghee mein lagatar hilate hue bhunein, jab tak sunehri aur nutty khushbu na aaye, taqreeban 8 se 10 minute.","Garam paani aur cheeni ehtiyat se daalein, ubalega, hilate hue pakayein jab tak halwa gaarha na ho jaye, phir ilaichi daal kar halki aanch par 5 minute dhak dein.","Tail garam karein, piyaz naram hone tak fry karein, tamatar, aloo, garam masala, haldi aur laal mirch daal kar masala achhi tarah bhunein.","Chane aur in ka pakane wala paani daalein, 10 minute simmer karein, aur kuch chanon ko kinare par mash kar ke gravy gaarhi karein.","Chhoti puriyan belein, sikke ke kinare se moti nahi, aur garam tail mein deep fry karein, halke se dabate hue taake har aik phool jaye. Kagaz par drain karein.","Puri, halwa aur chane aik plate mein ikathe serve karein, halwe par badam daal kar."],"tip":"Puri belte waqt zyada maida na lagayein, warna phulegi nahi. Tail achha garam ho to puri foran phool jati hai, is liye pehle atte ke chhote tukde se test karein, wo seconds mein upar aana chahiye.","notes":["Sakht atta phuli hui puri banata hai. Naram atta tail pee leta hai aur chapta rehta hai, is liye sakht gundhein aur achhi tarah rest dein.","Bareek suji hamwar halwa deti hai. Moti suji ko zyada paani aur zyada waqt chahiye.","Chanon ke pakane ka paani bacha kar rakhein. Is se gravy qudrati tor par gaarhi hoti hai aur zaiqa aata hai.","Ilaichi halwe mein aakhir mein daalein, taake is ki khushbu taazi rahe, pak kar khatam na ho."],"variations":["Chanon ki jagah aloo ki tarkari: aloo ko wahi masale mein pakayein, aadhe mash kar lein, aur savoury side ke tor par serve karein.","Kam meetha halwa: cheeni 3/4 cup kar dein aur thodi zyada ilaichi daalein, masaledar chanon ke sath behtar lagne wale halwe ke liye.","Whole wheat puri: aadha whole wheat atta aur aadha maida lein, atte ko thoda zyada rest dein, aur thoda mota belein."],"serving":"4 logon ke liye, har shakhs ko 2 se 3 puri, aik chamach halwa, aur aik plate mein chanon ka bara chamach kaafi hai. Achar, kati hui piyaz aur lemon ke sath, aur side par chai ke sath serve karein. Halwa puri baith kar khane wala nashta hai, garam garam, sab table par ikathe. Zyada puri banayein, kyunke wo sab se jaldi khatam hoti hai.","storage":"Puri taazi khayein, wo achhi nahi rehti. Halwa fridge mein airtight dabbe mein 3 din tak rehta hai, aur halki aanch par pan mein thode doodh ya paani ke sath dobara garam hota hai. Chane fridge mein 3 din tak rehte hain, aur stove par ubalne tak dobara garam hote hain. Tayyar plate store na karein, teeno hisse alag rakhein aur serve karte waqt milayein.","mistakes":["Puri ko zyada mota belna ya zyada khushk maida lagana. Wo chapti aur chewy rehti hai, phoolti nahi.","Suji ko tez aanch par bhunna. Wo jagah jagah brown ho jati hai aur jali hui lagti hai, is liye aanch halki rakhein aur hilayein.","Garam suji mein thanda paani daalna. Is se gutliyan ban jati hain, is liye garam paani use karein aur foran hilayein.","Puri ko kam garam tail mein fry karna. Wo tail pee leti hai aur greasy ho jati hai."],"faq":[["Meri puri kyun nahi phoolti?","Atta zyada naram tha, puri zyada moti beli gayi, ya tail kaafi garam nahi tha. Sakht gundhein, patla belein, aur pehle tail test karein."],["Kya tinned chane use kar sakte hain?","Ji haan. Drain kar ke dho lein, phir masale mein 10 minute simmer karein. Thoda garam paani daalein, kyunke tinned chanon ke paas pakane ka paani nahi hota."],["Halwa kitna meetha hona chahiye?","Riwayati halwa puri ka halwa kaafi meetha hota hai, masaledar chanon ko balance karne ke liye. Kam meetha pasand ho to cheeni kam karein, lekin aadhi na karein, warna texture badal jata hai."],["Kya hisse pehle se bana sakte hain?","Ji haan. Halwa aur chane aik din pehle bana kar fridge mein rakhein. Puri subah taazi fry karein, kyunke dobara garam ki hui puri kabhi utni achhi nahi hoti."]]},"samosa":{"intro":"Achhe samose ka faisla pehle niwale mein hota hai, kurkuri parat jo toot jaye, phir matar, adrak aur dhaniye ke sath masaledar aloo. Parat sakht aur rest di hui honi chahiye, filling khushk honi chahiye, geeli nahi, aur frying halki aanch par ahista honi chahiye, taake crust andar tak sunehri ho, aik minute mein brown ho kar andar se pheeki na rahe. Ye recipe classic Punjabi samosa banati hai, jo hari aur imli ki chutney aur chai ke cup ke sath serve hota hai. Double batch banayein, kyunke ye jaldi khatam ho jate hain, aur extra ko fry karne se pehle freeze kar lein kisi aur din ke liye.","ing":["Maida 2 cup","ajwain 1/2 tsp","Aloo (uble hue) 4","matar 1/2 cup","Adrak","hari mirch","garam masala","Hara dhaniya","anar dana","Talne ke liye tail"],"steps":["Ajwain aur 3 tbsp tail ko ungliyon se maide mein mal lein, jab tak wo breadcrumbs jaisa na lage.","Thoda thoda paani daal kar sakht, stiff atta gundhein. Wo naram nahi hona chahiye. Dhak kar 20 minute rest dein.","Aloo ko sirf naram hone tak ubalein, thanda karein, aur mota mota tod lein. Isay hamwar mash na karein.","1 tbsp tail garam karein, adrak aur hari mirch 30 second fry karein, matar, garam masala, namak aur anar dana daal kar 2 minute pakayein.","Aloo aur dhaniya daalein, achhi tarah milayein, aur 2 se 3 minute pakayein jab tak filling khushk na ho jaye. Isay bilkul thanda kar lein.","Atte ko goliyon mein baantein, har aik ko oval belein, aadha kaatein, aur cone banayein, seedha kinara paani se band kar ke.","Har cone ko teen chauthai bharein, upar wala kinara mazbooti se band karein, aur dabakar band karein. Check karein ke filling bahar na nikle.","Halki aanch par tail mein 12 se 15 minute fry karein, beech beech mein palat kar, jab tak gehra sunehra aur kurkura na ho jaye. Drain kar ke chutney ke sath serve karein."],"tip":"Samosa hamesha halki aanch par fry karein. Tez aanch par parat jal jayegi aur andar kacha reh jayega, aur crust kurkura aur aik jaisa hone ke bajaye bubble ban jayega.","notes":["Sakht atta kurkuri parat ka raaz hai. Naram atta chewy, oily samosa banata hai.","Bharne se pehle filling ko bilkul thanda kar lein. Garam filling andar se parat mein bhaap banati hai aur seal kamzor kar deti hai.","Ajwain classic zaiqa deti hai aur hazme mein madad karti hai. Mil jaye to na chhodein.","Khushk filling ahm hai. Geeli filling leak hoti hai, parat ko naram karti hai, aur frying ko messy bana deti hai."],"variations":["Qeema samosa: aloo ki jagah paka hua, masaledar qeema lein, bilkul thanda kar ke, aur wahi tareeqe se fry karein.","Paneer samosa: matar, garam masala aur dhaniye ke sath crumbled paneer use karein, zyada rich vegetarian filling ke liye.","Baked samosa: tail brush kar ke 190C par 20 se 25 minute bake karein, aik dafa palat kar. Kam kurkura, lekin halka."],"serving":"6 logon ke liye, har shakhs ko 2 samose, hari chutney, imli ki chutney, kati hui piyaz aur garam chai ke sath kaafi hai. Platter par serve karein, aik ko kaat kar filling dikhayein, aur side par zyada chutney rakhein. Samosa fry karne ke 30 minute ke andar garam garam behtareen hota hai, jab parat abhi kurkuri ho. Upar chhidka hua thoda chaat masala khatta finish deta hai.","storage":"Behtareen kurkurepan ke liye taaza khayein. Thande, tale hue samose fridge mein 2 din tak rehte hain aur oven mein 180C par 8 se 10 minute dobara garam hote hain, jab tak dobara kurkure na ho jayein. Microwave na karein, kyunke parat naram ho jati hai. Kache, shape diye hue samoson ko tray par freeze karein, phir bag mein daal kar 1 mahine tak rakhein, aur frozen hi halki aanch par fry karein, 3 se 4 minute zyada dein.","mistakes":["Naram atta gundhna. Wo asani se belta hai, lekin naram aur oily fry hota hai.","Garam, geeli filling bharna. Seal khul jati hai aur filling tail mein leak ho jati hai.","Tez aanch par fry karna. Bahar jaldi brown ho jata hai aur andar ki parat doughy reh jati hai.","Cone ko zyada bharna. Wo tail mein phat jate hain, is liye sirf teen chauthai bharein."],"faq":[["Mere samose ki parat kurkuri kyun nahi, naram kyun hai?","Atta zyada naram tha, ya frying ki aanch zyada tez thi. Sakht gundhein, atte ko rest dein, aur halki aanch par ahista fry karein."],["Kya samose air fryer mein bana sakte hain?","Ji haan. Tail brush kar ke 180C par 12 se 15 minute air fry karein, aik dafa palat kar. Crust kurkura hota hai, halanke deep fried se thoda khushk hota hai."],["Samosa fry karte waqt khulne se kaise rokein?","Paani se band karein aur mazbooti se dabayein, aur shape diye hue samoson ko fry karne se pehle 10 minute rest dein, taake seal set ho jaye."],["Kya ready made pastry use kar sakte hain?","Zaroorat ho to spring roll sheets use kar sakte hain, lekin zaiqa aur texture mukhtalif hota hai. Classic kurkurapan is recipe ke sakht maide ke atte se aata hai."]]},"bunkebab":{"intro":"Bun kebab Karachi ka street food hai jis ke wafadar chahne wale hain, naram bun, tala hua shami kabab, kati hui piyaz aur tamatar, aur chutney jo har niwale mein mirch, khattapan aur taazgi lati hain. Ye ghar par 25 minute mein banne wala fast food hai, bas shami kabab tayyar hon, aur tawe se seedha garam khana behtareen hai, bun halka seka hua aur phir bhi naram. Balance kisi aik ingredient se zyada ahm hai. Zyada chutney kabab ko dooba deti hai, kam chutney bun ko khushk chhod deti hai, aur achha seka hua bun sab kuch ikatha rakhta hai baghair haathon mein tootne ke.","ing":["Shami kabab 8","bun 4","Piyaz","tamatar","hari chutney","Imli ki chutney","dahi","Hari mirch","hara dhaniya","Bun sekne ke liye makhan"],"steps":["Piyaz ko patle rings mein kaatein, tamatar kaatein, aur chutney, mirch aur dhaniya chhote bowls mein tayyar rakhein.","Tawe par darmiyani aanch par thoda tail garam karein. Shami kabab ko har taraf 2 se 3 minute fry karein, jab tak andar tak garam aur kinaron par halke kurkure na ho jayein.","Kabab nikaal kar garam rakhein. Tawa halka saaf karein, makhan daalein, aur bun ke kate hue hisse ko halka sunehra hone tak sekein, taqreeban 1 minute.","Neeche wale bun par hari chutney aur upar wale bun par imli ki chutney lagayein. Patli teh kaafi hai, kabab hi star rehna chahiye.","Har neeche wale bun par 2 kabab rakhein. Agar kabab chhote hon to thode overlap kar dein taake har niwale mein kabab ho.","Piyaz rings, tamatar, hari mirch aur dhaniya daalein. Thanda, creamy niwala pasand ho to aik chamach phenti hui dahi daalein.","Bun band kar ke halke se dabayein. Chutney sirf kinaron tak pahunchni chahiye, tapakni nahi chahiye.","Foran garam serve karein, side par zyada chutney aur thande drink ke sath. Dono haathon se khayein, Karachi style."],"tip":"Bun ko zyada na sekein. Halka sunehra kaafi hai, warna sakht aur tootne wala ho jayega, aur kabab andar baithne ke bajaye bahar phisal jayega.","notes":["Shami kabab andar se naram aur bahar se halke kurkure hone chahiye. Agar bohat naram hon to fry karne se pehle 15 minute thanda karein, taake shape rakhein.","Naram burger bun lein, sakht roll nahi. Bun ko kabab ke gird halke se dabna chahiye, ladna nahi chahiye.","Imli ki chutney meethi khatti note deti hai. Pehle chakhein, kyunke kuch bohat meethi hoti hain aur kam chahiye.","Piyaz rings kurkure rehte hain agar serve karne se pehle kaatein. Kaati hui piyaz der tak rakhi rahe to naram aur tez ho jati hai."],"variations":["Chicken bun kebab: chicken shami kabab lein aur thodi zyada hari chutney daalein, kyunke chicken beef se halka hota hai.","Anda bun kebab: kabab ke upar tala hua anda rakhein, zardi sirf set ho, zyada rich street style version ke liye.","Mirch wala bun kebab: kati hui hari mirch aur aik chamach chilli garlic sauce daalein, aur dahi chor dein."],"serving":"4 logon ke liye, har shakhs ko 1 bun kebab, zyada chutney, aur side par saada salad ya fries kaafi hai. Bun kebab street food hai, is liye isay kagaz mein lapet kar ya plate mein, tawe se garam serve karein, aur foran khayein. Is ke sath thandi lassi, fizzy drink, ya chai achhi lagti hai. Bari bheed ke liye bun, kabab aur chutney table par rakhein aur log khud banayein.","storage":"Bun kebab taaza khana behtareen hai aur assemble karne ke baad achha nahi rehta, kyunke bun chutney pee leta hai. Hisse alag rakhein. Pake hue shami kabab fridge mein 2 din tak rehte hain aur tawe par dobara garam hote hain. Chutney band jar mein fridge mein 4 din tak rehti hai. Serve karne se pehle hi sekhein aur assemble karein, taake bun naram aur kabab garam rahe.","mistakes":["Bun ko zyada sekna. Wo sakht ho jata hai, toot jata hai, aur filling bahar gir jati hai.","Kabab ko chutney mein doobana. Balance khatam ho jata hai aur bun minutes mein geela ho jata hai.","Kabab ko bohat tez aanch par fry karna. Bahar jal jata hai aur beech mein thanda reh jata hai.","Jaldi assemble karna. Bun nami pee leta hai aur kurkure kinare khane se pehle naram ho jate hain."],"faq":[["Shami kabab kya hota hai?","Naram kabab jo qeeme aur daal se banta hai, paka kar, pees kar aur shape de kar, phir fry kiya jata hai. Ye bun mein dabne ke liye naram hota hai, sakht seekh kabab ki tarah nahi."],["Kya frozen shami kabab use kar sakte hain?","Ji haan. Frozen hi darmiyani aanch par fry karein, har taraf 1 se 2 minute zyada dein, jab tak andar tak garam na ho jaye. Pehle thaw na karein, kyunke naram kabab toot jate hain."],["Sab se achha bun kaun sa hai?","Naram, saada burger bun. Til wala bun bhi chal jata hai. Sakht roll na lein, kyunke wo toot jata hai aur filling bahar gir jati hai."],["Kya imli ki chutney ke baghair bana sakte hain?","Ji haan. Zyada hari chutney aur lemon ka ras khattapan ke liye use karein. Zaiqa mukhtalif hota hai, lekin phir bhi achha kaam karta hai."]]},"gulabjamun":{"intro":"Gulab jamun wo mithai hai jo aksar celebrations ke aakhir mein aati hai, naram, garam, aur gulab ki khushbu wali chashni mein doobi hui jab tak wo is se bhari na ho jaye. Raaz ingredients ki lambi list nahi hai. Ye taaza aur naram khoya hai, halke haath se gundha hua atta, halki aanch par frying taake jamun andar tak pak jayein baghair jaldi zyada brown hue, aur chashni jo garam ho, ubalti hui nahi, jab wo is mein jayein. Kisi bhi hisse mein jaldi karein to jamun sakht, darar wale, ya andar se khushk ho jate hain. Waqt lein, aur wo phool jayenge, naram honge, aur chamkenge. Inhein garam serve karein, upar chashni daal kar, aur dekhein ke kaise khatam ho jate hain.","ing":["Khoya 250g","maida 3 tbsp","Ilaichi powder 1/2 tsp","Cheeni 2 cup","paani 2 cup","Gulab ka pani 1 tsp","lemon ke 2 drops","Talne ke liye tail / ghee"],"steps":["Khoye ko tod kar maida aur ilaichi ke sath gundhein jab tak naram, hamwar atta na ban jaye. Zyada na gundhein, warna jamun ghane ho jayenge.","Atte ko dhak kar 15 minute rest dein. Wo itna naram hona chahiye ke baghair darar ke roll ho jaye.","Cheeni, paani aur lemon ras ko garam kar ke chashni banayein jab tak cheeni ghul na jaye. 5 minute simmer karein, ilaichi aur gulab ka pani daalein, aur garam rakhein, ubalta hua nahi.","Hatheliyon par halka ghee lagayein. Chhoti, hamwar goliyan banayein, akhrot ke size ki, surface par koi darar na ho.","Tail ya ghee ko halki se darmiyani halki aanch par garam karein. Tail itna garam ho ke halke se sizzle kare, foran brown karne jitna garam nahi.","Jamun ko batches mein daalein, chamach se halke se hilate hue taake wo roll hon aur aik jaise brown hon, 6 se 8 minute, jab tak halke sunehre na ho jayein.","Jamun nikaal kar seedha garam chashni mein daalein. Wo halke se sizzle karenge aur phoolna shuru kar denge.","Kam az kam 1 ghanta rest dein, aik dafa palat kar, taake jamun aik jaise chashni peeyein. Garam serve karein, upar chashni daal kar."],"tip":"Jamun mein darar nahi honi chahiye. Goliyan banate waqt haathon par halka ghee lagayein. Chashni zyada garam na ho, warna jamun peene ke bajaye sakht ho jayenge, aur thandi bhi na ho, warna wo isay jazb nahi karenge.","notes":["Taaza, naram khoya naram jamun banata hai. Khushk, tootne wala khoya atte ko jodne ke liye aik chamach doodh mangta hai.","Maida sirf bandhne ke liye hai. Zyada maida sakht jamun banata hai, is liye naap kar daalein aur chipchipe atte ko theek karne ke liye zyada na daalein, rest dein.","Chashni mein lemon ras isay thanda hone par crystallise hone se rokta hai, is liye chashni saaf aur hamwar rehti hai.","Gulab ka pani aanch se utaar kar daalein, taake is ki khushbu taazi rahe, ubal kar khatam na ho."],"variations":["Kesar jamun: aik chutki zafran ko garam doodh mein bhigo kar chashni mein daalein, aur pista se garnish karein.","Stuffed jamun: fry karne se pehle har goli ke beech mein khushk mewa aur nut mix ka chhota tukda dabayein.","Ice cream ke sath jamun: garam jamun ko vanilla ice cream par rakhein, upar garam chashni daal kar, garam aur thandi dessert ke liye."],"serving":"6 logon ke liye, har shakhs ko chhote bowls mein 3 se 4 jamun, khoob chashni ke sath kaafi hai. Garam serve karein, pasand ho to kate hue pista se garnish karein, aur dosri dafa ke liye zyada chashni jug mein rakhein. Gulab jamun Eid, shadi aur dinner party ke liye behtareen hai, aur chamach se bowl se seedha khana behtareen hai. Is ke baad chai ka cup classic finish hai.","storage":"Chashni mein dhake hue dabbe mein fridge mein 4 din tak rakhein. Chashni mein halki aanch par ahista dobara garam karein, ya microwave mein 20 se 30 second, jab tak garam ho, zyada garam nahi. Inhein chashni mein na ubalein, kyunke wo toot jate hain. Chashni ke baghair 1 mahine tak freeze karein, fridge mein thaw karein, aur serve karne se pehle taazi chashni mein garam karein.","mistakes":["Tez aanch par fry karna. Bahar jaldi dark ho jata hai aur andar kacha aur ghana reh jata hai.","Darar wali goliyan banana. Chashni aik jaisi nahi jati aur jamun phat jate hain ya khurdure ho jate hain.","Jamun ko ubalti hui chashni mein daalna. Surface band ho jati hai aur wo andar se sakht rehte hain.","Atte ko zyada gundhna. Wo sakht ho jata hai aur jamun apni narmi kho dete hain."],"faq":[["Mere gulab jamun sakht kyun hain?","Atta zyada gundha gaya, zyada maida use hua, ya chashni zyada garam thi. Halke se gundhein, maida naap kar daalein, aur chashni ko garam rakhein, ubalta hua nahi."],["Kya khoye ki jagah milk powder use kar sakte hain?","Ji haan. 1 cup milk powder ko 2 tbsp ghee aur 3 se 4 tbsp garam doodh ke sath naram atta bana lein, phir wahi steps follow karein. Texture qareeb hota hai, halanke khoya zyada naram hota hai."],["Mere jamun chashni mein kyun toot gaye?","Wo kam fry hue, atta zyada naram tha, ya chashni ubal rahi thi. Halke sunehre aur sakht hone tak fry karein, aur chashni ko garam rakhein."],["Kya chashni kam meethi bana sakte hain?","Cheeni ko 1½ cup tak kam kar sakte hain, lekin chashni ko jamun ko dhakna chahiye. Bohat patli chashni wahi tareeqe se nahi peeti, is liye is se zyada kam na karein."]]},"gajarhalwa":{"intro":"Gajar ka halwa sardiyon ka bowl hai, laal gajar doodh mein ahista pakti hai jab tak doodh khatam na ho jaye, phir ghee mein cheeni ke sath bhuni jati hai aur khoya, ilaichi aur nuts se mukammal hoti hai. Ye jaldi wali dessert nahi hai, aur yahi is ki baat hai. Lambi, halki cooking kaddukas ki hui gajar ko naram, rich aur gehre zaiqe wali cheez bana deti hai, aur koi shortcut waisa zaiqa nahi deta. Laal gajar mile to wahi lein, bareek kaddukas karein, aur aanch halki rakhein. Isay garam serve karein, upar khoye ka chamach daal kar, aur agle din ke liye kuch bacha lein, kyunke phir aur behtar lagta hai.","ing":["Laal gajar 1 kg (kaddukas ki hui)","Doodh 1 litre","cheeni 1 cup","Ghee 4 tbsp","khoya 150g","Ilaichi 4","badam / pista"],"steps":["Gajar ko dho kar, chheel kar bareek kaddukas karein. Bareek kaddukas ahm hai, kyunke moti shreds zyada waqt leti hain aur khurduri rehti hain.","Gajar aur doodh ko bhari kadhai mein rakhein. Ubal layein, phir halki aanch kar dein.","Baghair dhake halki aanch par 35 se 45 minute pakayein, har kuch minute mein hilate hue, jab tak doodh taqreeban khushk na ho jaye.","Ghee daal kar gajar ko hilate hue 8 se 10 minute bhunein, jab tak mixture chamkila na ho jaye aur kinaron ko chhodne lage.","Cheeni daal kar 8 se 10 minute aur pakayein, hilate hue, jab tak cheeni ghul na jaye aur halwa dobara gaarha na ho jaye.","Ilaichi koot kar khoye ke sath daalein. 5 minute hilate hue pakayein, jab tak khoya halwe mein ghul na jaye.","Chakhein aur adjust karein. Zyada meetha ho to lemon ka ras riwayati nahi hai, is liye chhoti portions baghair meethi chai ke sath serve karein.","Garam serve karein, upar kate hue badam aur pista aur thoda zyada khoya daal kar."],"tip":"Gajar bareek kaddukas karein. Moti gajar der se pakti hai aur halwa khurdura rehta hai, chahe kitni der hilayein, is liye shuru mein kaddukas karne mein waqt lein.","notes":["Laal gajar zyada meethi hoti hai aur gehra rang deti hai. Narangi gajar bhi chal jati hai, lekin halwa halka rang ka hota hai aur thodi zyada cheeni chahiye.","Full fat doodh zyada rich result deta hai. Low fat doodh ko kam hone mein zyada waqt lagta hai aur zaiqa patla hota hai.","Aakhir mein khoya richness aur body deta hai. Achha khoya khareedna worth hai, ya zaroorat ho to paneer ko tod kar substitute bana lein.","Ilaichi ko taaza kootna chahiye. Pehle se pisi hui ilaichi ki khushbu jaldi khatam ho jati hai."],"variations":["Milk powder halwa: aadhe doodh ki jagah 1 cup milk powder gajar mein mila dein, jaldi aur rich version ke liye.","Nutty halwa: khoye ke sath kate hue kaju aur kishmish daalein, aur nuts ko pehle ghee mein toast karein.","Kam meetha halwa: cheeni 3/4 cup kar dein. Halwa gajar se phir bhi meetha hota hai, aur ice cream ke sath serve karne ke liye behtareen hai."],"serving":"5 logon ke liye, chhote bowls mein, garam, kate hue nuts aur upar khoye ke chamach ke sath kaafi hai. Gajar ka halwa sardiyon ki dessert hai, dinner ke baad ya dopahar ki chai ke sath serve hoti hai. Garam halwe par vanilla ice cream ka scoop popular modern serving hai, aur garam aur thande ka contrast khoobsurat lagta hai. Portions chhoti rakhein, kyunke ye rich hai.","storage":"Thanda kar ke airtight dabbe mein fridge mein 4 din tak rakhein. Pan mein halki aanch par thode doodh ke sath hilate hue dobara garam karein, jab tak andar tak garam na ho jaye. Microwave mein chhote bursts mein bhi achha garam hota hai. Hisson mein 1 mahine tak freeze karein, fridge mein thaw karein, aur thode doodh ke sath dobara garam karein. Taaze nuts serve karte waqt daalein, kyunke rakhe hue nuts naram ho jate hain.","mistakes":["Tez aanch par pakana. Doodh lag kar jal jata hai, aur halwa jala hua lagta hai.","Cheeni jaldi daalna. Is se paani nikalta hai aur gajar kam hone ke bajaye ubal jati hai, is liye doodh khushk hone ke baad daalein.","Mota kaddukas karna. Halwa chahe kitni der pake, stringy aur khurdura rehta hai.","Ghee mein bhunne ka stage chhodna. Is ke baghair halwa ubla hua lagta hai, rich aur chamkila nahi."],"faq":[["Kya narangi gajar use kar sakte hain?","Ji haan. Halwa halke rang ka aur thoda kam meetha hota hai, is liye chakhein aur zaroorat ho to 1 se 2 tbsp zyada cheeni daalein. Laal gajar sardiyon ke halwe ke liye riwayati hai."],["Kaise pata chalega ke doodh kaafi kam ho gaya hai?","Mixture khushk lagta hai, gajar ikathi rehti hai, aur hilate waqt kinaron par ghee alag hota nazar aata hai. Wahi waqt hai ghee daal kar bhunne ka."],["Kya khoye ke baghair bana sakte hain?","Ji haan. Phir bhi achha hota hai, bas kam rich hota hai. Aakhir mein 2 extra tbsp ghee aur 2 tbsp milk powder daalein, ya naram paneer tod kar daalein."],["Gajar ka halwa garam serve hota hai ya thanda?","Garam behtareen hai, kadhai se seedha ya halke se dobara garam kar ke. Fridge se thanda halwa sakht aur kam khushbudar hota hai, is liye serve karne se pehle garam karein."]]},"lassi":{"intro":"Mango lassi garmiyon ka glass hai, pake hue aam thande dahi, thode doodh, aur ilaichi ke sath blend kiye jate hain, jab tak wo gaarhi, hamwar aur itni thandi na ho jaye ke aap ko thanda kar de. Is mein 15 minute lagte hain, zyada waqt aam chheelne mein hai, aur is mein pakana bilkul nahi hai. Aam ki quality sab kuch tay karti hai, is liye wo phal chunein jo stem par meethi khushbu de, dabane par halka dabe, aur jis mein hara, sakht hissa na ho. Isay foran thande glass mein serve karein, upar thoda kata hua aam daal kar, aur peeyein jab tak blender ka foam upar ho.","ing":["Pake hue aam 2","dahi 1½ cup","Doodh 1/2 cup","cheeni 2 tbsp (zaiqe ke mutabiq)","Ilaichi powder 1/4 tsp","Barf ke cubes (podina garnish ke liye)"],"steps":["Glass ko fridge mein 15 minute thanda karein, taake lassi peete waqt thandi rahe.","Aam chheel kar gutli se gosht alag karein, aur mota mota kaat lein. Aik tukda chakhein aur tay karein ke kitni cheeni chahiye.","Aam, dahi, doodh, cheeni aur ilaichi blender mein daalein. Barf abhi na daalein.","30 second blend karein, rokein, kinaron ko scrape karein, aur 30 second aur blend karein, jab tak bilkul hamwar na ho jaye.","Mutthi bhar barf ke cubes daalein aur 15 se 20 second aur blend karein, sirf jab tak barf koot jaye aur lassi gaarhi aur thandi na ho jaye.","Chakhein aur adjust karein. Aam khatta ho to thodi zyada cheeni daalein, ya zyada gaarhi ho to thoda doodh daalein.","Foran thande glass mein daalein, foam upar rehne dein.","Kate hue aam aur podine ke patte se garnish karein, aur straw ya chamach ke sath foran serve karein."],"tip":"Aam jitna meetha, cheeni utni kam chahiye. Lassi pehle se na banayein. Taazi blended behtareen hoti hai, kyunke rakhi rehne par alag ho jati hai aur foam khatam ho jata hai, aur barf pighal kar isay patla kar deti hai.","notes":["Mausam mein Sindhri, Chaunsa ya Alphonso jaise pake, meethe aam use karein. Reshe wale aam stringy lassi banate hain, is liye zaroorat ho to chhaan lein.","Full fat dahi gaarhi, creamy lassi deti hai. Low fat dahi bhi chal jati hai, lekin lassi patli hoti hai aur kam doodh chahiye.","Ilaichi background note honi chahiye, asal zaiqa nahi. 3 glass ke liye quarter tsp kaafi hai.","Sab kuch pehle thanda karein. Thanda aam, thanda dahi aur thanda doodh matlab kam barf chahiye, aur zaiqa strong rehta hai."],"variations":["Mango banana lassi: 1 paka hua kela daalein, gaarhi, meethi lassi ke liye jo bachon ko pasand aati hai.","Mango rose lassi: 1 tsp gulab ka pani aur aik chutki zafran daalein, aur gulab ki pankhudiyon se garnish karein.","Vegan lassi: coconut dahi aur oat doodh use karein, aur zaiqe ke mutabiq maple syrup ya cheeni se meetha karein."],"serving":"3 logon ke liye, lambe thande glass mein, upar kate hue aam aur podine ke sath kaafi hai. Mango lassi garam dopahar, mirch wale khane, aur garmiyon ke weekend ke nashtay ke liye behtareen hai. Isay parathe aur achar ke sath drink ke tor par, ya mirch wali curry ke baad halki dessert ke tor par serve karein. Daalne ke waqt tak thanda rakhein, aur taazi peeyein.","storage":"Behtareen texture ke liye taazi peeyein. Lassi band jar mein fridge mein 1 din tak rehti hai, lekin alag ho jati hai, is liye serve karne se pehle achhi tarah hilayein ya shake karein, aur foam wapas aane ki umeed na rakhein. Lassi ko freeze na karein, kyunke thaw hone par dahi daane wali ho jati hai. Agar pehle se banana hi ho to aam aur dahi ko barf ke baghair blend karein, fridge mein rakhein, aur serve karne se pehle barf daal kar dobara blend karein.","mistakes":["Kacha aam use karna. Kitni bhi cheeni khatte, sakht zaiqe ko theek nahi karti, is liye pake hue phal ka intezar karein.","Barf ke sath zyada blend karna. Lassi gaarhi aur creamy hone ke bajaye paani wali aur patli foamy ho jati hai.","Shuru mein zyada doodh daalna. Wo lassi ko patla kar deta hai pehle hi, is liye doodh thoda thoda daalein.","Ghanton pehle banana. Wo alag ho jati hai, rang halka ho jata hai, aur taaze aam ka zaiqa khatam ho jata hai."],"faq":[["Kya frozen aam use kar sakte hain?","Ji haan. Isay aadha thaw karein, taake blend karne ke liye naram ho lekin phir bhi thanda ho, aur barf aadhi kar dein. Frozen aam bohat gaarhi lassi banata hai, is liye doodh thoda thoda daalein."],["Kya mango lassi healthy hai?","Ye phal aur dahi se banti hai, aur yahan koi numbers nahi diye gaye. Cheeni wo hissa hai jis par dhyan dein, is liye pake hue aam use karein aur jitni zaroorat ho utni hi cheeni daalein."],["Kya lassi blender ke baghair bana sakte hain?","Ji haan, agar aam bohat naram ho. Aam ko kaante se mash karein, dahi aur doodh whisk karein, aur chhalni se guzarein. Wo utni hamwar nahi hoti, lekin phir bhi mazedar hoti hai."],["Meri lassi stringy kyun hai?","Aam reshe wala tha. Zyada der blend karein, ya serve karne se pehle bareek chhalni se guzarein. Agli dafa kam reshe wali variety chunein."]]},"pizza":{"intro":"Margherita pizza is baat ka saboot hai ke saada khana bhi behtareen ho sakta hai. Ye Naples mein mashhoor hui, jahan garam oven, patli crust, taaza tamatar ki sauce aur achhi mozzarella sara kaam karte hain. Is ke rang Italian jhande ki yaad dilate hain, laal tamatar, safed mozzarella aur hara basil, aur zaiqa bhari nahi, saaf aur taaza hota hai. Is recipe mein dough ko itni der rest diya jata hai ke wo halki aur chewy ho jaye, sauce halki si pakti hai, aur bohat garam oven mein crust chand minute mein phool jati hai. Dough aur garam oven par tawajjo dein, to ghar ke oven se bhi pizzeria jaisa pizza banega.","ing":["Strong bread flour 500g","neem garam pani 325ml","Instant yeast 7g","bareek namak 10g","olive oil 2 tbsp","San Marzano tamatar 400g (kuchle hue)","Fior di latte mozzarella 250g (tooti hui)","Taaze basil ke patte 1 muthi","Lehsan 1 clove","sauce ke liye olive oil","namak","Dusting ke liye semolina ya maida"],"steps":["Maida, pani, yeast aur namak mila kar 8 se 10 minute goondhein jab tak naram na ho jaye, phir dhak kar 1 ghanta rest dein, ya behtar zaiqe ke liye raat bhar fridge mein rakhein.","Tamatar ko lehsan, chutki bhar namak aur 1 tbsp olive oil ke sath kuchal lein. Sauce ko pakayein nahi, wo pizza par pak jayegi.","Dough ko 4 hisson mein baant lein, 20 minute rest dein, phir har hissay ko haath se beech se bahar ki taraf phelaein, kinare ko mota rakhein.","Oven ko jitna garam ho sake, kam az kam 250C par garam karein, andar pizza stone ya ulta baking tray 30 minute ke liye garam karein.","Har base par 3 se 4 tbsp sauce phelaein, kinara khaali rakhein, aur upar tooti hui mozzarella daalein.","6 se 8 minute bake karein jab tak crust phool kar sunehri na ho jaye aur cheese bulbule na banane lage.","Pizza nikalte hi basil ke patte daalein, taake wo halke se naram ho jayein aur jal na jayein.","Upar se thora olive oil daalein, kaatein, aur crust kurkura rehte hi foran serve karein."],"tip":"Pizza par zyada topping na daalein. Sauce ki patli teh aur munasib cheese se crust achhi tarah pakti hai aur kurkuri rehti hai.","notes":["Bread flour se wo chew milti hai jo saada maida nahi de sakta, is liye agar mile to wohi use karein, aur maida ko tol kar lein.","Fior di latte pani mein rakhi naram mozzarella hoti hai. Isay nikaal kar todein aur halka sa khushk karein, taake pizza geela na ho.","San Marzano tamatar meethe aur kam khatte hote hain. Agar dosra tin use karein to achhi tarah kuchal lein aur sirf zaroorat par chutki bhar cheeni daalein.","Peel par semolina dough ko chipakne se rokti hai aur halki si kurkurahat deti hai. Sirf maida tez garam oven mein jal sakta hai."],"variations":["Marinara: cheese chor dein, extra lehsan aur oregano daalein, aur olive oil ke sath finish karein, dairy free pizza ke liye.","Four cheese: tamatar sauce ki jagah olive oil ki patli teh lagayein, phir mozzarella, gorgonzola, fontina aur parmesan daalein.","Cherry tamatar ke sath: aadhe cherry tamatar ko olive oil ke sath roast karein, phir kuchle hue tamatar ki sauce ki jagah use karein."],"serving":"4 logon ke liye hai, har shakhs ke liye aik pizza, ya salad ke sath baant kar khane ke liye slice kaat lein. Oven se nikalte hi serve karein, extra basil, chilli oil ya parmesan table par rakhein, aur har koi apni marzi se daale. Pizza pehle 10 minute mein sab se behtareen hota hai, jab base kurkura aur cheese naram aur khinchne wali hoti hai.","storage":"Bachi hui slice fridge mein airtight dabbe mein 2 din tak rakhi ja sakti hain. Dobara garam oven ya dhakkan wali khushk karahi mein garam karein, taake base phir kurkura ho jaye. Microwave se bachein, is se crust naram ho jati hai. Kachhi dough fridge mein 3 din tak aur freezer mein 1 mahine tak rakhi ja sakti hai, fridge mein raat bhar rakh kar thaw karein.","mistakes":["Thanda oven use karna. Crust phoolne ke bajaye steam mein pakti hai, is liye stone ya tray ko poori tarah garam karein.","Dough ko belan se belna. Is se hawa nikal jati hai, is liye haath se phelaein.","Zyada sauce ya cheese daalna. Beech geela rehta hai aur base kurkura nahi hota.","Bohat garam oven mein bake karne se pehle basil daalna. Wo kaala ho jata hai, is liye bake ke baad daalein."],"faq":[["Meri pizza base beech mein geeli kyun hoti hai?","Oven ya stone poori tarah garam nahi tha, ya sauce aur cheese zyada thi. Poori tarah preheat karein, topping kam rakhein, aur sab se neeche wali shelf par bake karein."],["Kya dough pehle se bana sakta hoon?","Ji haan. Goondhne ke baad 3 din tak fridge mein rakhein. Phelane se pehle 30 se 45 minute room temperature par rakhein."],["Kya pizza stone zaroori hai?","Nahi. Oven mein garam kiya hua ulta bhari baking tray bhi achha kaam karta hai. Cast iron pan se bhi kurkura base milta hai."],["Kya sookha basil use kar sakta hoon?","Yahan taaza basil bohat behtar hai, kyunke yehi asal zaiqa hai. Sauce mein sookha basil theek hai, lekin finish ke liye taaze patte daalein."]]},"carbonara":{"intro":"Asli carbonara mein cream nahi hoti. Ye Rome se hai, aur is ki sauce sirf ande, pecorino cheese, kaali mirch aur guanciale ya pancetta ki charbi se banti hai, garam pasta ke sath mila kar jab tak wo chamakdar aur naram na ho jaye. Ahm baat garam ka control hai. Pan itna garam hona chahiye ke ande halke se sauce mein pak jayein, lekin itna garam nahi ke wo scramble ho jayein. Jaldi kaam karein, sauce ko dheela karne ke liye pasta ka pani use karein, aur foran serve karein. Timing seekh lein to ye sab se tez aur sukoon dene wali pasta dishes mein se aik ban jati hai, sirf chand ajza ke sath aur gehre zaiqe ke sath.","ing":["Spaghetti 400g","Guanciale ya pancetta 150g (chhote tukde)","Ande ki zardi 4","aur 1 poora anda","Pecorino Romano 60g (bareek kaddukas)","Kaali mirch 2 tsp (taazi kooti hui)","Pasta ke pani ke liye namak","Serve ke liye extra pecorino","mirch"],"steps":["Spaghetti ko achhi tarah namak wale pani mein al dente tak ubalein, aur chhanne se pehle 1 cup pasta ka pani bacha lein.","Guanciale ya pancetta ko khushk pan mein darmiyani aanch par 6 se 8 minute fry karein jab tak kinare kurkure na ho jayein aur charbi pighal na jaye.","Zardi, poora anda, pecorino aur zyada tar kaali mirch ko gaarha paste banane tak phentein. Agar zyada sakht ho to aik chamach pasta ka pani daalein.","Pan ko aanch se utaar lein aur 1 minute thanda hone dein, taake ande pan se milte hi scramble na hon.","Chhana hua spaghetti pan mein daalein aur pighli hui charbi mein 30 second achhi tarah milayein.","Ande aur cheese ka mix daalein aur tez aur musalsal milayein, thora thora pasta ka pani daalte hue jab tak sauce chamakdar na ho jaye aur har strand par lag na jaye.","Chakhein, aur mirch daalein, aur namak sirf zaroorat par daalein, kyunke pecorino aur pancetta pehle hi namkeen hain.","Garam piyalon mein foran serve karein, upar extra pecorino aur kaali mirch daal kar."],"tip":"Ande daalne se pehle pan ko aanch se utaar lein. Bachi hui garmi sauce banati hai, seedhi aanch ande scramble kar deti hai.","notes":["Pecorino Romano tez aur namkeen hota hai, aur yehi rawaiti cheese hai. Parmesan bhi chalti hai, lekin halki hoti hai, is liye thori zyada use karein aur namak daalne se pehle chakhein.","Guanciale cured pork cheek hota hai aur classic zaiqa deta hai. Pancetta sab se qareebi asaan badal hai, aur bacon bhi chalta hai, halanke zyada smoky hota hai.","Pasta ka pani starch se bhara hota hai. Ye ande ki sauce ko spaghetti par chipakne mein madad karta hai.","Taazi kooti hui kaali mirch yahan ahm hai. Ye asal zaiqa hai, sirf garnish nahi, is liye moti kooten aur khoob use karein."],"variations":["Matar ke sath: aakhri minute mein pasta ke pani mein aik muthi matar daalein, rang aur mithaas ke liye.","Vegetarian style: pork ki jagah makkhan aur olive oil mein fry ki hui mushroom use karein, aur thori smoked paprika daalein, halanke nateeja mukhtalif dish hogi.","Halki version: 4 zardi ki jagah 2 poore ande aur 2 zardi use karein, aur thori kam cheese, sauce phir bhi naram hogi."],"serving":"4 logon ke liye main course ke tor par hai, garam piyalon mein, saath saada green salad aur kurkuri roti ke sath. Carbonara aik piyale ka khana hai, is liye side dishes halki rakhein aur pasta ko star rehne dein. Milate hi serve karein, kyunke sauce thandi hote hi gaarhi ho jati hai aur narmi kho deti hai.","storage":"Carbonara taazi khana behtar hai aur dobara garam karne par achhi nahi rehti, kyunke ande ki sauce gaarhi ho kar phat sakti hai. Agar rakhna hi ho to 1 din tak fridge mein rakhein aur thore pani ke sath pan mein bohat halki aanch par musalsal hilate hue garam karein. Freeze na karein. Sirf paka hua pasta 2 din tak rehta hai, lekin sauce taazi banayein.","mistakes":["Ande ko aanch par rakhe hue pan mein daalna. Ande scramble ho jate hain aur sauce dana daar ho jati hai.","Cream use karna. Is se mukhtalif, bhari sauce banti hai aur pecorino ka zaiqa chhup jata hai.","Pasta ka sara pani phenk dena. Is ke baghair sauce zyada gaarhi hoti hai aur pasta par nahi lagti.","Chakhne se pehle namak daalna. Pecorino aur cured pork namkeen hote hain, is liye pehle chakhein."],"faq":[["Kya guanciale ki jagah bacon use kar sakta hoon?","Ji haan. Kurkura hone tak fry karein, aur agar charbi zyada ho to thori nikaal lein. Zaiqa zyada smoky hoga, lekin tareeqa wohi hai."],["Meri sauce scramble kyun ho gayi?","Pan zyada garam tha. Aanch se utaar lein, aik minute thanda karein, aur agli dafa pasta ke pani ke sath jaldi milayein."],["Kya pork ke baghair carbonara bana sakta hoon?","Ji haan, mushroom ya matar ke sath, lekin wo classic carbonara jaisa zaiqa nahi dega. Ande aur pecorino ki sauce wohi rakhein."],["Pasta ke pani ki miqdar kaise maloom karun?","Chhoti si miqdar se shuru karein aur milate hue aur daalte jayein. Sauce chamakdar aur dheeli lagni chahiye, gaarhi aur paste jaisi nahi."]]},"sushi":{"intro":"Sushi mein pehle chawal ahm hain, machhli baad mein. Japan mein chawal ko sirka, cheeni aur namak se season kiya jata hai, pankhe se thanda kiya jata hai, aur narmi se handle kiya jata hai taake har dana alag aur chamakdar rahe. Ye ghar wali version salmon aur kheere ke roll banati hai, jo seekhne mein sab se asaan hain, bahar nori, beech mein chawal, aur filling ki saaf line. Sushi grade salmon use karein, haath geele rakhein, aur mazbooti se lekin narmi se roll karein. Pehla roll tedha lag sakta hai, aur ye normal hai. Teesre roll tak shape, cut aur confidence sab aa jate hain, aur nateeja taaza aur saaf hota hai.","ing":["Sushi chawal 2 cup (kachhe)","Chawal ka sirka 4 tbsp","cheeni 2 tbsp","namak 1 tsp","Nori sheet 4","Sushi grade salmon 300g (strips mein kata hua)","Kheera 1 (patli sticks mein kata hua)","Mayonnaise 3 tbsp","sriracha 1 tsp (spicy mayo ke liye)","Serve ke liye soy sauce","pickled adrak","wasabi","Til 1 tbsp (optional)"],"steps":["Chawal ko dhoein jab tak pani saaf na ho jaye, pakayein, phir dhak kar 10 minute rest dein.","Sirka, cheeni aur namak ko garam karein jab tak ghul na jayein, garam chawal mein halke se milayein, aur pankha jhal kar thanda karein jab tak halka garam aur chamakdar na ho jaye.","Nori sheet ko chamakdar taraf neeche bamboo mat par rakhein, haath geele karein, aur chawal ki patli barabar teh phelaein, door wale kinare par 2cm khaali rakhein.","Beech mein spicy mayo ki patli line lagayein, salmon aur kheere ki sticks aik saaf qataar mein rakhein, aur til chhidkein.","Mat ke qareebi kinare ko uthayein aur apni taraf se door mazbooti se roll karein, filling ko andar karte hue, aur khaali kinare ko thore pani se band karne ke liye halka dabayein.","Roll ko 2 minute rest dein, phir geele tez chhure se 8 hisson mein kaatein, har cut ke darmiyan blade ko ponchhein.","Bache hue chawal aur filling ke sath dohraein, haath geele rakhte hue.","Hisson ko kati hui taraf upar rakh kar sajayein, aur soy sauce, pickled adrak aur thori si wasabi ke sath serve karein."],"tip":"Paas mein pani ka piyala rakhein aur haath aur chhura aksar geela karein. Geele haath chawal ko chipakne se rokte hain, aur geela blade roll ko dabaye baghair saaf kaatta hai.","notes":["Sushi chawal chhote dane wala chawal hota hai. Lambe dane wala chawal usi tarah nahi chipakta, is liye saaf roll ke liye isay badlein nahi.","Sushi grade ka matlab hai kachha khane ke liye bechi jane wali machhli, jo pakde jane se le kar bikne tak thandi rakhi jaye. Machhli wale se poochein, aur aam machhli use na karein jo pakane ke liye hoti hai.","Chawal ka sirka halka aur meetha hota hai. Is ki jagah tez malt sirka na use karein, jo chawal par haawi ho jayega.","Nori kurkuri aur gehri honi chahiye. Isay band aur khushk rakhein, kyunke geeli nori phat jati hai aur saaf roll nahi hoti."],"variations":["Tuna roll: salmon ki jagah sushi grade tuna use karein, aur kheere ki jagah avocado daalein.","Pake hue prawn roll: pake hue prawn, kheera aur thori mayo use karein, agar aap kachhi machhli nahi chahte to achha intikhab hai.","Sabzi roll: kheera, avocado, gajar ki sticks aur pickled mooli use karein, til ke sath, poori vegetarian roll ke liye."],"serving":"4 logon ke liye halke khane ke tor par hai, har shakhs ke liye 2 roll, ya miso soup aur salad ke sath bare Japanese khane ke hisse ke tor par. Kaatne ke foran baad room temperature par serve karein, soy sauce ke sath, har piece ke darmiyan munh saaf karne ke liye pickled adrak, aur wasabi kam use karein. Sushi haath se khane wala khana hai, is liye chopsticks aur chhoti platein rakhein, aur har koi khud serve kare.","storage":"Sushi usi din khana behtar hai, roll karne ke chand ghanton ke andar. Fridge chawal ko khushk aur machhli ko bezaaiqa kar deta hai, is liye aik din pehle na banayein. Agar rakhna hi ho to kas kar dhak kar 6 ghante tak fridge mein rakhein, phir serve karne se 20 minute pehle room temperature par le aayein. Sushi ko freeze na karein. Sirf paka hua sushi chawal fridge mein 1 din tak rehta hai.","mistakes":["Garam chawal use karna. Ye nori ko naram kar deta hai aur roll toot jata hai, is liye chawal ko halka garam hone tak thanda karein.","Roll mein zyada filling bharna. Zyada filling se roll band nahi hota, is liye filling ko aik saaf qataar tak rakhein.","Sookhe chhure se kaatna. Chawal chipak jata hai, is liye har cut se pehle blade geela karein.","Roll karte hue zyada zor lagana. Chawal dab jata hai aur filling bahar nikal aati hai, is liye mazbooti se lekin narmi se roll karein."],"faq":[["Kya ghar par kachha salmon khana mehfooz hai?","Sirf tab jab wo bharosemand dukaan se sushi grade salmon ho, thanda rakha gaya ho, aur usi din khaya jaye. Shak ho to pake hue prawn ya sabzi use karein."],["Kya bamboo mat ke baghair sushi bana sakta hoon?","Ji haan. Cling film ke neeche tea towel, ya baking paper use karein. Mat asaan bana deti hai, lekin zaroori nahi."],["Mera chawal chipchipa aur naram kyun hai?","Wo kaafi dhoya nahi gaya, ya season karte hue zor se hilaya gaya. Achhi tarah dhoein aur seasoning ko narmi se milayein."],["Kya chawal pehle se bana sakta hoon?","Ji haan, chand ghante pehle. Room temperature par dhak kar rakhein, fridge mein nahi, aur serve karne se pehle hi roll karein."]]},"ramen":{"intro":"Ramen aik piyale mein sukoon hai, aur achhi ghar wali version ke liye sara din simmer hone wali broth ki zaroorat nahi. Ye chicken ramen jaldi zaiqa banata hai, lehsan, adrak aur hari piyaz ko sesame oil mein fry kar ke, chicken stock ko soy aur miso se gehra kar ke, aur noodles ko alag paka kar taake broth saaf rahe aur noodles springy rahein. Anda aakhri touch hai, beech mein naram aur broth se season hota hua. Topping chhote piyalon mein rakhein aur har koi apna piyala khud banaye, garam broth aakhir mein, taake noodles baith kar naram na hon. Ye tez, garam aur bohat sukoon dene wala hai.","ing":["Chicken breast ya thigh 500g","Chicken stock 1.5 litre","Ramen noodles 4 hissay","Lehsan 4 clove","adrak 3cm tukda","Soy sauce 3 tbsp","miso paste 2 tbsp","Sesame oil 1 tbsp","hari piyaz 4","Ande 4 (naram ubale hue)","Serve ke liye chilli oil","til","nori"],"steps":["Ande ko 6.5 minute ubalein, thande pani mein thanda karein, chheel lein, aur serve karne se pehle aadha kaatein.","Bare pot mein sesame oil garam karein, lehsan, adrak aur hari piyaz ke safed hisse ko 2 minute fry karein jab tak khushbu na aaye.","Chicken stock daalein, soy sauce daalein, aur 15 minute halki aanch par simmer karein taake zaiqe mil jayein.","Chicken ko simmer hoti broth mein 12 se 15 minute pakayein jab tak pak na jaye, phir nikaal kar slice karein aur garam rakhein.","Miso ko aik karchhi garam broth ke sath phentein jab tak naram na ho jaye, phir wapas pot mein milayein. Miso daalne ke baad tez na ubalein.","Noodles ko packet ke mutabiq alag pakayein, achhi tarah chhanein, aur 4 garam piyalon mein baant lein.","Garam broth noodles par daalein, upar chicken ki slice, ande ke aadhe hisse, hari piyaz aur til rakhein.","Chilli oil aur nori ke sath foran serve karein, aur broth ke steam karte hue khayein."],"tip":"Noodles ko alag pakayein. Broth mein pake hue noodles broth ko soakh lete hain, broth ko ganda kar dete hain, aur serve karne se pehle naram ho jate hain.","notes":["Miso gehraai aur namak daalta hai. Safed miso halka aur meetha hota hai, laal miso tez hota hai, is liye laal use karein to kam se shuru karein.","Taaze ramen noodles 2 se 3 minute mein pakte hain aur springy rehte hain. Sookhe noodles bhi chalte hain, lekin packet ka waqt dekhein aur zyada na pakayein.","Adrak ko kata hua hona chahiye, bareek nahi, taake wo broth ko ganda ya dana daar kiye baghair zaiqa de.","Sesame oil zaiqe ke liye hai, tez aanch par fry karne ke liye nahi. Darmiyani aanch par shuru mein daalein, aur dhuaan na nikalne dein."],"variations":["Spicy ramen: miso ke sath broth mein 1 tbsp chilli paste ya gochujang milayein.","Sabzi ramen: chicken ki jagah mushroom aur tofu use karein, aur sabzi ka stock use karein, wohi khushbudar ajza rakhte hue.","Pork ramen: chicken ki jagah patli kati hui paki hui pork use karein, aur upar sweetcorn aur bean sprout daalein."],"serving":"4 logon ke liye hai, gehre piyalon mein, chopsticks aur soup ke chamach ke sath, aur topping table ke beech mein. Broth ko steam karte hue serve karein, extra chilli oil, soy sauce aur til haath mein rakhein, taake har shakhs apna piyala khud season kar sake. Ramen foran khaya jata hai, jab noodles springy aur anda garam ho, is liye broth daalne se pehle sab ko table par bulayein.","storage":"Broth fridge mein 3 din tak rehti hai, aur 1 mahine tak freeze ho sakti hai. Noodles aur topping milane ke baad achhi nahi rehti, is liye alag rakhein aur taaza assemble karein. Broth ko ubalne tak garam karein, taaze noodles pakayein, aur topping serve karne se pehle daalein. Bacha hua kata hua chicken fridge mein 2 din tak rehta hai.","mistakes":["Miso daalne ke baad broth ko tez ubalna. Is se zaiqa halka ho jata hai, is liye halki simmer rakhein.","Noodles ko zyada pakana. Wo garam broth mein naram ho jate hain, is liye springy hone tak pakayein aur achhi tarah chhanein.","Anda jaldi daalna. Wo garam broth mein zyada pak jata hai, is liye aadha anda bilkul aakhir mein daalein.","Thande piyalon mein serve karna. Broth jaldi thandi ho jati hai, is liye pehle piyalon ko garam pani se garam karein."],"faq":[["Kya instant noodles use kar sakta hoon?","Ji haan, lekin flavour sachet phenk dein aur is broth ko use karein. Noodle block ko alag pakayein aur achhi tarah chhanein."],["Kya broth pehle se bana sakta hoon?","Ji haan. 3 din pehle tak bana kar fridge mein rakhein. Ubalne tak garam karein, phir miso taaza daalein aur piyale assemble karein."],["Jammy anda kaise milega?","Fridge se thanda anda 6.5 minute ubalein, foran thande pani mein thanda karein, aur narmi se chheelein. Zardi naram aur halki si set honi chahiye."],["Kya ramen bohat namkeen hota hai?","Ho sakta hai. Extra soy sauce daalne se pehle chakhein, kyunke stock, soy aur miso sab namak daalte hain."]]},"tacos":{"intro":"Tacos al pastor Mexico City mein Lebanese shawarma se shuru hue, aur phir poori tarah Mexican ban gaye, sookhi mirchon aur achiote mein marinated pork, kinaron par charred, aur garam corn tortilla mein ananas, piyaz aur dhaniya ke sath. Marinade asal kaam karta hai, is liye isay waqt dein, 30 minute bhi farq daalte hain, aur raat bhar behtar hai. Pork ko tez aur jaldi pakayein taake wo sookhe baghair char ho jaye, tortilla ko khuli aanch ya khushk pan mein garam karein, aur topping saada rakhein. Meethe ananas ka dhuaan daar, masaledar pork ke sath mel hi asal baat hai, is liye isay chorain nahi, aur lime aur salsa ke sath serve karein.","ing":["Pork shoulder 700g (patli kati hui)","Sookhi guajillo mirch 3","ancho mirch 1","Achiote paste 2 tbsp","lehsan 3 clove","Safed sirka 3 tbsp","orange juice 60ml","Zeera 1 tsp","oregano 1 tsp","namak","Ananas 300g (tukdon mein kata hua)","Corn tortilla 12","safed piyaz 1","dhaniya","Lime 2","apni pasand ki salsa"],"steps":["Sookhi mirchon ko garam pani mein 15 minute bhigoyein jab tak naram na ho jayein, phir chhanein, thora bhigoya hua pani bacha kar.","Mirch, achiote, lehsan, sirka, orange juice, zeera, oregano aur namak ko naram marinade banane tak blend karein, zaroorat par bhigoya hua pani daalte hue.","Pork ko marinade mein lapetein, dhak kar fridge mein kam az kam 30 minute, ya behtareen zaiqe ke liye raat bhar rakhein.","Bare pan ya griddle ko tez aanch par thore oil ke sath garam karein, aur pork ko hisson mein har taraf 3 se 4 minute pakayein jab tak char na ho jaye aur pak na jaye.","Usi garam pan mein ananas ke tukdon ko har taraf 1 se 2 minute sear karein jab tak kinare sunehre na ho jayein.","Pork ko chhote tukdon mein kaatein aur ananas aur pan ke ras ke aik chamach ke sath milayein.","Tortilla ko khushk pan mein ya aanch par garam karein jab tak naram aur halki si daaghdaar na ho jayein, aur kapde mein lapet kar rakhein.","Har tortilla mein pork aur ananas bharein, upar kati hui piyaz aur dhaniya daalein, aur lime aur salsa ke sath serve karein."],"tip":"Hisson mein pakayein aur pan ko bharain nahi. Bhara hua pork char hone ke bajaye steam mein pakta hai, aur aap wo kurkure kinare kho dete hain jo al pastor ko khaas banate hain.","notes":["Achiote paste laal rang aur mitti jaisa zaiqa deta hai. Mexican dukaanon ya online se milega, aur sirf food colour se badlein nahi.","Guajillo mirch halki aur phal jaisi hoti hai. Ancho gehraai daalti hai. Kam mirch chahiye to beej nikaal dein, aur sookhi mirch ko haath lagate hue gloves pehnein.","Pork shoulder tez aur jaldi pakane par juicy rehti hai. Lean pork loin jaldi sookhta hai, is liye patla kaatein aur kam waqt pakayein.","Corn tortilla rawaiti hain. Flour tortilla bhi chalti hain, lekin naram hoti hain aur juicy filling ko kam sambhalti hain."],"variations":["Chicken al pastor: wohi marinade ke sath chicken thigh use karein, aur char hone tak pakayein, halki version ke liye.","Avocado ke sath: kata hua avocado aur lime ka ras daalein, ananas ko bhi rakhte hue, creaminess ke liye.","Zyada spicy version: marinade mein 1 chipotle in adobo daalein, aur saath garam salsa serve karein."],"serving":"4 logon ke liye hai, har shakhs ke liye 3 tacos, aur lime, salsa, extra piyaz aur dhaniya table par. Taco bharte hi serve karein, jab tortilla garam aur pork abhi sizzling ho, aur har koi apna lime aur salsa khud daale. Saada chawal aur beans, ya kurkuri band gobhi ki salad, taco ko poora khana bana deti hai baghair un se tawajjo hataye.","storage":"Marinated kachha pork fridge mein 1 din tak rehta hai. Paka hua pork fridge mein 3 din tak rehta hai, aur garam pan mein thore pani ke sath dobara garam karne par behtar rehta hai, taake phir kurkura ho jaye. Tortilla room temperature par lapet kar 1 din, ya fridge mein 3 din tak rehti hain, aur khushk pan mein garam ho jati hain. Bhare hue taco store na karein, wo geele ho jate hain. Ananas alag se 2 din tak rehta hai.","mistakes":["Thanda pan use karna. Pork marinade mein ubal jata hai char hone ke bajaye, is liye pehle pan ko dhuaan nikalne tak garam karein.","Marinade ka waqt chor dena. 30 minute bhi ahm hain, aur sirf 5 minute marinated pork ka zaiqa pheeka hota hai.","Tortilla mein zyada bharna. Wo phat jati hain aur filling gir jati hai, is liye har taco mein 2 se 3 tbsp pork use karein.","Lime bhool jana. Khatta ras rich pork ko halka karta hai, is liye hamesha lime serve karein."],"faq":[["Kya pork ko grill kar sakta hoon?","Ji haan. Tez aanch par har taraf 3 se 4 minute grill karein, phir kaat kar ananas ke sath milayein. Griddle pan ghar ke andar sab se qareebi nateeja deta hai."],["Agar achiote paste na mile to kya karun?","1 tbsp smoked paprika, 1 tsp pisa zeera aur chutki bhar haldi rang ke liye use karein. Zaiqa mukhtalif hoga, lekin kaam chal jayega."],["Kya corn tortilla gluten free hain?","Sirf makai, pani aur lime se bani khaalis corn tortilla qudrati tor par gluten free hoti hain, lekin packet par cross contamination check karein agar ye ahm ho."],["Kya marinade pehle se bana sakta hoon?","Ji haan. Blend kar ke 3 din tak fridge mein, ya 1 mahine tak freeze kar ke rakhein. Pork ko pakane wale din marinate karein."]]},"pozole":{"intro":"Pozole Mexico ki celebration soup hai, hominy ke sath banai jati hai, bare safed makai ke dane jo lambe simmer mein phool kar naram ho jate hain, aur pork jo chamach se tootne tak pakta hai. Laal version ka rang aur gehraai sookhi guajillo aur ancho mirchon se aati hai, jo naram blend kar ke broth mein milai jati hain, jabke topping taazi aur kurkuri rehti hain, kata hua band gobhi, mooli, piyaz, oregano aur lime. Is mein waqt lagta hai, lekin zyada waqt baghair tawajjo ke guzarta hai, aur aik pot bohat logon ko khila deta hai. Weekend par pakayein, broth ko rich aur topping ko alag rakhein, aur har koi apna piyala table par khud finish kare.","ing":["Pork shoulder 1kg (bare tukdon mein kata hua)","Safed hominy 800g (chhana, dhoya hua)","Sookhi guajillo mirch 4","ancho mirch 2","Piyaz 1","lehsan 6 clove","Tez patta 2","oregano 2 tsp","zeera 1 tsp","Namak","pani ya halka stock 3 litre","Serve ke liye kata band gobhi","mooli","piyaz","lime","Serve ke liye sookha oregano","chilli flakes"],"steps":["Sookhi mirchon ko garam pani mein 15 minute bhigoyein, chhanein, aur lehsan aur thore bhigoye hue pani ke sath naram blend karein.","Pork, hominy, piyaz, tez patta aur pani ko bare pot mein daalein, ubal le aayein, aur upar aane wali jhaag utaar lein.","Halki simmer par rakhein, aadha dhak dein, aur 90 minute pakayein, agar pani kam ho to garam pani daalte hue.","Blend ki hui mirch ki sauce ko chhalni se chhan kar pot mein daalein, achhi tarah milayein, aur namak, zeera aur oregano se season karein.","30 minute aur simmer karein jab tak pork naram ho kar tootne lage aur broth rich aur laal ho jaye.","Pork nikaal lein, do kaanton se kaat lein, aur wapas pot mein daalein. Chakhein aur namak aur mirch theek karein.","Pozole finish hote hue topping tayyar karein, kata band gobhi, patli mooli, kati piyaz, lime aur oregano.","Gehre piyalon mein daalein, khoob topping daalein, aur saath garam tortilla serve karein."],"tip":"Mirch ki sauce ko daalne se pehle chhanein. Chhalni chilke aur beej rok leti hai, aur broth naram aur silky rehti hai dana daar hone ke bajaye.","notes":["Hominy lime se treat ki hui makai hoti hai, jis se dane bare, naram aur hazam mein asaan ho jate hain. Tin wali hominy tayyar hoti hai, sookhi hominy ko raat bhar bhigona aur zyada pakana parta hai.","Guajillo mirch rang aur halki phal jaisi garmi deti hai. Ancho gehri, kishmish jaisi gehraai daalti hai. Dono mil kar classic laal broth banati hain.","Pork shoulder mein itni charbi hoti hai ke lambe simmer mein juicy rehta hai. Lean pork sookh jata hai, is liye tukde bare rakhein aur simmer halki rakhein.","Shuru mein jhaag utaar lein. Is se broth saaf aur zaiqa saaf rehta hai."],"variations":["Hari pozole: laal mirchon ki jagah tomatillo, hari mirch aur dhaniya use karein, blend kar ke usi tarah daalein.","Chicken pozole: pork ki jagah haddi wali chicken thigh use karein, aur simmer ka waqt taqreeban 45 minute kar dein.","Vegetarian pozole: sabzi ke stock ke sath mushroom aur beans use karein, aur wohi mirch sauce aur topping daalein."],"serving":"6 logon ke liye hai, gehre piyalon mein, topping alag piyalon mein table ke beech mein. Har shakhs kurkurahat ke liye band gobhi, bite ke liye mooli, piyaz, oregano aur khoob lime daalta hai, jo rich broth ko halka karta hai. Scoop karne ke liye garam corn tortilla ke sath serve karein, aur zyada garmi chahne walon ke liye extra chilli flakes side par rakhein.","storage":"Pozole fridge mein 4 din tak rehti hai, aur raat bhar rakhne se zaiqa behtar ho jata hai. Broth aur pork ko ikatha, aur topping ko alag rakhein. Halki aanch par ubalne tak garam karein, agar gaarhi ho gayi ho to thora pani daalein. 3 mahine tak freeze ho sakti hai, fridge mein raat bhar rakh kar thaw karein. Taazi topping ko freeze na karein.","mistakes":["Poora waqt tez ubalna. Pork sakht ho jata hai aur broth ganda ho jata hai, is liye halki simmer rakhein.","Mirch ki sauce ko chhane baghair daalna. Chilke aur beej broth ko dana daar bana dete hain.","Taazi topping ke baghair serve karna. Wo sajawat nahi hain, wo kurkurahat aur khattapan se rich broth ko balance karte hain.","Broth mein kam namak daalna. Aakhir mein chakhein, kyunke hominy aur pork ko chamakne ke liye achhi miqdar mein namak chahiye."],"faq":[["Kya pressure cooker use kar sakta hoon?","Ji haan. Pork aur hominy ko pressure par 35 se 40 minute pakayein, phir khule pot mein mirch sauce ke sath 10 minute finish karein."],["Kya pozole bohat spicy hoti hai?","Laal version garam hoti hai, bohat tez nahi. Halki broth ke liye mirch ke beej nikaal dein, aur table par chilli flakes se garmi daalein."],["Kya sookhi hominy use kar sakta hoon?","Ji haan, lekin raat bhar bhigoyein aur pork daalne se pehle naram hone tak simmer karein, jis mein aik ghanta extra lag sakta hai."],["Pozole ke sath kya serve karun?","Garam corn tortilla, aur yahan di gayi taazi topping. Saada salad ki zaroorat nahi, topping hi salad hain."]]},"padthai":{"intro":"Pad thai Thailand ki sab se mashhoor noodle dish hai, aur is ka jaadu balance mein hai, meetha, khatta, namkeen aur thori garmi, sab aik garam wok mein. Sauce imli, fish sauce, palm sugar aur mirch se banti hai, aur wo chawal ke noodles par lagti hai jo bhigoye jate hain, ubale nahi jate, taake wo naram hone ke bajaye springy rahein. Prawn, anda, bean sprout aur chives tez aanch par jaldi daale jate hain, aur dish ko kooti hui moongphali, lime aur extra sprout ke sath finish kiya jata hai. Shuru karne se pehle sab kuch tayyar rakhein, kyunke wok garam hote hi pakana sirf chand minute leta hai, aur yehi tezzi noodles ko naram hone se bachati hai.","ing":["Chapti chawal noodles 250g","Prawn 300g (chheele hue)","Ande 2 (halke phente hue)","Imli ka paste 3 tbsp","fish sauce 3 tbsp","Palm sugar ya brown sugar 3 tbsp","Lehsan 3 clove","chilli flakes 1 tsp","Bean sprout 2 cup","garlic chives ya hari piyaz","Bhuni moongphali 4 tbsp (kooti hui)","lime 1"],"steps":["Chawal ke noodles ko neem garam pani mein 20 se 30 minute bhigoyein jab tak lachakdaar lekin sakht rahein, phir achhi tarah chhanein.","Imli, fish sauce, cheeni aur chilli flakes ko mila kar sauce banayein, aur chakhein. Wo aik sath meethi, khatti aur namkeen honi chahiye.","Wok mein tez aanch par oil garam karein, lehsan ko 20 second fry karein, phir prawn daalein aur 2 minute pakayein jab tak halke gulabi na ho jayein.","Prawn ko aik taraf karein, ande daalein, aur halke se scramble karein jab tak set na ho jayein, phir prawn ke sath milayein.","Chhane hue noodles aur sauce daalein, aur 2 se 3 minute musalsal milayein jab tak noodles naram na ho jayein aur sauce jazb na ho jaye.","Aadhe bean sprout aur chives daalein, 30 second milayein, aur wok ko aanch se utaar lein.","Platon mein baant lein, upar bache hue sprout, kooti hui moongphali aur hari piyaz daalein.","Lime, extra chilli flakes aur fish sauce ke sath foran serve karein, taake har shakhs apni marzi se theek kar sake."],"tip":"Noodles ko bhigoyein, ubalein nahi. Uble hue noodles wok mein zyada pak jate hain aur naram aur chipchipe ho jate hain.","notes":["Imli ka paste khatta note deta hai jo pad thai ko pehchan deta hai. Agar bohat gaarha ho to sauce milane se pehle thore garam pani se patla karein.","Palm sugar caramel jaisi mithaas mein pighalta hai. Brown sugar achhi chalti hai, lekin safed cheeni tez hoti hai, is liye thori kam use karein.","Fish sauce namkeen aur tez khushbu wali hoti hai. Isay sauce mein daalein, seedha wok mein nahi, taake barabar mile.","Chapti chawal noodles motai mein mukhtalif hoti hain. Patli noodles jaldi bhigti hain, is liye 15 minute baad check karein aur sakht rehte hue chhanein."],"variations":["Chicken pad thai: prawn ki jagah patli kati hui chicken use karein, ande daalne se pehle achhi tarah pakayein.","Tofu pad thai: sakht tofu use karein, pehle sunehra hone tak fry karein, vegetarian version ke liye, aur check karein ke fish sauce ka badal aap ko suit karta ho.","Extra sabzi: noodles ke sath kata hua gajar aur kata band gobhi daalein, zyada kurkurahat aur rang ke liye."],"serving":"4 logon ke liye hai, garam platon par, lime, kooti hui moongphali, extra bean sprout aur chilli flakes table par. Pad thai street food hai, is liye garam aur casual serve karein, har koi apni plate par lime nichode aur apni marzi se moongphali ya garmi daale. Saath halki kheere ki salad taazgi deti hai, lekin tawajjo noodles par rakhein.","storage":"Pad thai taazi khana behtar hai, seedha wok se. Bacha hua khana fridge mein 1 din tak rehta hai, aur garam wok ya pan mein thore pani ke sath musalsal hilate hue dobara garam hota hai. Noodles dobara garam karne par naram ho jate hain, is liye wohi texture ki umeed na rakhein. Freeze na karein. Sirf sauce fridge mein 1 hafte tak rehti hai.","mistakes":["Noodles ko zyada pakana. Chhanne par sakht hone chahiye, kyunke wo sauce mein pak kar mukammal hote hain.","Wok ka kaafi garam na hona. Noodles steam mein pakte hain aur chipak jate hain, is liye wok ko dhuaan nikalne tak garam karein.","Sare sprout jaldi daalna. Wo murjha kar naram ho jate hain, is liye aadhe aakhir mein daalein aur aadhe topping ke liye kachhe rakhein.","Sauce ko chakhna bhool jana. Pakane se pehle balance karein, kyunke noodles daalne ke baad meetha, khatta aur namkeen theek nahi ho sakta."],"faq":[["Kya fish sauce ke baghair pad thai bana sakta hoon?","Ji haan, chutki bhar namak ke sath soy sauce, ya vegetarian fish sauce use karein. Zaiqa mukhtalif hoga, lekin meetha aur khatta balance rehta hai."],["Agar mere noodles chipak jayein to kya karun?","Wo zyada der bhige, ya wok kaafi garam nahi tha. Achhi tarah chhanein, thore oil ke sath milayein, aur agli dafa zyada garam wok mein pakayein."],["Kya sookhi shrimp use kar sakta hoon?","Ji haan. 2 tbsp sookhi shrimp bhigoyein aur lehsan ke sath daalein. Wo rawaiti namkeen gehraai daalti hain."],["Kya pad thai gluten free hai?","Chawal ke noodles qudrati tor par gluten free hote hain, lekin fish sauce aur imli ke paste mein additives ho sakte hain, is liye label check karein."]]},"pekingduck":{"intro":"Peking duck China ki azeem celebration dishes mein se aik hai, apni kurkuri skin ke liye mashhoor jo toot jati hai, aur gosht jo neeche juicy rehta hai. Raaz skin ko khushk karna aur roast karne se pehle glaze karna hai, taake charbi nikal jaye aur skin gehri lacquered sunehri ho jaye. Is ghar wali version mein skin ko khushk karne ke liye fridge mein raat bhar rest, maltose aur sirke ki saada glaze, aur garam oven use hota hai, phir kaatne se pehle rest. Rawaiti tareeqe se serve karein, patli mandarin pancake mein hoisin sauce, hari piyaz aur kheere ke sath, aur har koi apni khud assemble kare. Ye aik project hai, roz ka khana nahi, aur har minute ke qabil hai.","ing":["Poori duck 2 se 2.5kg","Maltose ya shehed 3 tbsp","chawal ka sirka 2 tbsp","Shaoxing wine 2 tbsp","five spice 1 tsp","Namak 1 tbsp","blanch karne ke liye ubalta pani","Mandarin pancake 12","Hoisin sauce 120ml","Hari piyaz 4","kheera 1","Cavity ke liye adrak","lehsan (optional)"],"steps":["Duck ko saaf karein, bohat achhi tarah khushk karein, aur kaante se skin par halke surakh karein, gosht ko chhede baghair.","Sink mein duck par ubalta pani daalein, jis se skin kas jati hai, phir dobara khushk karein.","Maltose, sirka, Shaoxing wine, five spice aur namak ko garam karein jab tak maltose ghul na jaye, aur poori duck par brush karein.","Duck ko baghair dhake fridge mein raat bhar rest dein, tray par rack ke upar, taake skin poori tarah khushk ho jaye.","200C par seene ki taraf upar 30 minute roast karein, phir 180C kar dein aur 60 se 75 minute aur roast karein, jab tak skin gehri sunehri aur kurkuri na ho jaye.","Aadhe waqt mein bachi hui glaze se aik dafa brush karein, aur agar pankh ki nokain jaldi brown ho jayein to foil se dhak dein.","Kaatne se pehle 20 minute rest dein, taake ras settle ho jaye aur skin kurkuri rahe.","Skin aur gosht ko patli slice mein kaatein, pancake garam karein, aur hoisin, hari piyaz aur kheere ke sath serve karein."],"tip":"Skin ko raat bhar khushk karein. Geeli skin oven mein steam mein pakti hai aur kabhi kurkuri nahi hoti, jabke khushk skin pighal kar khoobsurat lacquer ban jati hai.","notes":["Maltose classic chamak aur halki mithaas deta hai. Shehed bhi chalta hai, lekin jaldi brown hota hai, is liye aakhri 20 minute mein duck par nazar rakhein.","Five spice tez hota hai. Naap kar daalein, aur extra na daalein, warna duck par haawi ho jayega.","Duck ki skin ke neeche bohat charbi hoti hai. Skin mein surakh karne se wo nikal jati hai, aur rack par roast karne se duck apni charbi se door rehta hai.","Mandarin pancake patle aur naram hote hain. Serve karne se pehle 2 minute steam karein, aur dhak kar rakhein taake sookh na jayein."],"variations":["Dukaan ki duck ke sath: Chinese deli se roast duck lein, garam oven mein skin ko kurkura karein, aur usi tarah pancake aur hoisin ke sath serve karein.","Duck breast version: duck breast par nishan lagayein, skin ki taraf neeche sear karein jab tak kurkura na ho jaye, oven mein finish karein, aur pancake ke liye patla kaatein.","Plum sauce ke sath: meethi, phal jaisi finish ke liye hoisin ki jagah plum sauce use karein."],"serving":"6 logon ke liye hai, shared khane ke markaz ke tor par, kati hui duck platter par, garam pancake, hoisin, hari piyaz aur kheera table ke beech mein. Har shakhs pancake par hoisin lagata hai, duck aur skin ki chand slice, hari piyaz aur kheera daalta hai, aur roll kar leta hai. Saath halki soup ya stir fried sabzi serve karein, aur jab tak duck rahe pancake aate rahein.","storage":"Bachi hui duck fridge mein airtight dabbe mein 2 din tak rehti hai. Gosht ko dhake hue pan mein thore pani ke sath halki aanch par garam karein, aur skin ko alag se garam grill ya garam oven mein chand minute kurkura karein. Pancake fridge mein 2 din tak rehte hain aur steam se garam hote hain. Kati hui skin ko freeze na karein, wo kurkurahat kho deti hai.","mistakes":["Raat bhar khushk karna chor dena. Skin naram aur charbi wali rehti hai, oven kitna bhi garam ho.","Bohat kam temperature par roast karna. Charbi nahi nikalti, is liye skin kurkuri ke bajaye chikni hoti hai.","Jaldi kaatna. Ras nikal jata hai aur skin steam mein aa jati hai, is liye poore 20 minute rest dein.","Mote pancake use karna. Wo duck par haawi ho jate hain, is liye patle mandarin pancake use karein aur achhi tarah garam karein."],"faq":[["Kya chhote oven mein Peking duck bana sakta hoon?","Ji haan, agar duck ke aas paas hawa ho. Taqreeban 2kg ki chhoti duck asaan hoti hai, aur tareeqa wohi hai."],["Agar maltose na mile to kya karun?","Thore garam pani se patla kiya hua shehed use karein. Glaze thori gehri hogi, is liye roast ke aakhir mein nazar rakhein."],["Kya sirf duck ki taangein use kar sakta hoon?","Ji haan. Usi tarah khushk aur glaze karein, aur kurkura hone tak taqreeban 50 se 60 minute roast karein. Poori duck se asaan hoti hain."],["Meri duck ki skin kurkuri kyun nahi hui?","Skin kaafi khushk nahi thi, ya oven kaafi garam nahi tha. Raat bhar khushk karein, achhi tarah surakh karein, aur garam roast karein."]]},"dimsum":{"intro":"Dim sum ka matlab hai dil ko chhune wala khana, aur ye baant kar khane ke liye hota hai, chhote bamboo steamer aik ke baad aik table par aate hain, har aik mein mukhtalif bite. Ye ghar wali version do classic banati hai, prawn har gow, shaffaf wrapper ke sath, aur pork aur prawn siu mai, khule upar ke sath, dono halke se pakne tak steam kiye hue aur garam serve kiye hue. Wrapper ko halka haath aur thora sabr chahiye, lekin filling saada hai, aur steaming tez hai. Madad se banayein, aik filling bhare, aik fold kare, aur tayyar dumpling ko dhak kar rakhein taake sookh na jayein. Chai ke sath serve karein, Cantonese yum cha ki tarah, aur khane ko aahista chalne dein.","ing":["Prawn 300g (bareek kate hue)","Pork qeema 200g","Har gow ke liye wheat starch 120g","tapioca starch 60g","Siu mai ke liye wonton wrapper 20","Adrak 1 tbsp (kaddukas)","hari piyaz 2","Soy sauce 2 tbsp","sesame oil 1 tsp","safed mirch","Cheeni 1 tsp","Shaoxing wine 1 tbsp","Serve ke liye chilli oil","soy sauce","kaala sirka"],"steps":["Prawn, pork, adrak, hari piyaz, soy, sesame oil, cheeni, wine aur safed mirch ko mila kar filling banayein, aur 20 minute thanda karein.","Har gow wrapper ke liye wheat starch aur tapioca starch ko 180ml ubalte hue pani ke sath milayein, naram dough goondhein, aur dhak kar 15 minute rest dein.","Har gow dough ko log banayein, chhote tukdon mein kaatein, aur har aik ko cleaver ya belan se patla gol dabayein.","Har wrapper mein aik chamach filling rakhein, crescent mein fold karein, aur kinare ko mazbooti se pleat kar ke band karein.","Siu mai ke liye har wonton wrapper ke beech mein aik chamach filling rakhein, kinaron ko filling ke gird jama karein, aur halka dabayein taake upar khula rahe.","Bamboo steamer ko surakh wale baking paper ya band gobhi ke patton se line karein, aur dumpling ko jagah chor kar rakhein.","Har gow ko 6 se 7 minute aur siu mai ko 8 minute steam karein, jab tak wrapper shaffaf ya set na ho jaye aur filling pak na jaye.","Steamer mein hi foran serve karein, chilli oil, soy sauce aur kaale sirke ke sath, aur saath garam chai."],"tip":"Dumpling mein zyada filling na bharein. Aik level chamach filling saaf band hoti hai, jabke zyada filling steamer mein wrapper ko phaar deti hai.","notes":["Wheat starch har gow wrapper ko shaffaf aur nazuk banata hai. Saada maida wohi nateeja nahi dega, is liye Asian dukaan se wheat starch lein.","Dough ko har waqt dhak kar rakhein. Wo chand minute mein sookh jata hai aur fold karte hue phat jata hai.","Shape dene se pehle filling ko thanda karein. Thandi filling hissa karna asaan hoti hai aur wrapper mein shape rakhti hai.","Zaroorat par hisson mein steam karein. Bhare hue steamer chipak jate hain, aur dumpling uthate hue phat jate hain."],"variations":["Sabzi dim sum: gosht ki jagah bareek kati mushroom, band gobhi, gajar aur tofu use karein, usi tarah season kar ke.","Chicken dim sum: prawn ke sath chicken qeema use karein, aur kurkurahat ke liye water chestnut daalein.","Dukaan ke wrapper ke sath: dono ke liye gol dumpling wrapper use karein, pleat kar ke band karein, asaan version ke liye jo phir bhi behtareen zaiqa deta hai."],"serving":"4 logon ke liye hai, shared khane ke hisse ke tor par, har shakhs ke liye 5 se 6 dumpling, aur chai, aur saath saada kheere ki salad ya stir fried sabzi. Steamer ko dhakkan ke sath seedha table par serve karein, taake dumpling khane ke lamhe tak garam aur steam wale rahein. Dim sum chhote bite mein slow khana hai, is liye chai bharti rahein, steamer hisson mein layein, aur jaldi na karein.","storage":"Kachhe dumpling tray par 1 mahine tak achhi tarah freeze hote hain, phir bag mein. Frozen se 3 se 4 minute zyada steam karein. Pake hue dumpling fridge mein 1 din tak rehte hain, aur 3 minute steam se dobara garam hote hain, microwave mein nahi, jo wrapper ko sakht kar deta hai. Bachi hui filling fridge mein dhak kar 1 din tak rehti hai.","mistakes":["Zyada mote wrapper use karna. Wo steam ke baad aate jaisi rehti hai, is liye patla belen ya dabayein.","Sookhe steamer par steam karna. Dumpling chipak kar phat jate hain, is liye steamer ko line karein aur halka oil lagayein.","Dhakkan baar baar kholna. Steam nikal jata hai aur dumpling barabar nahi pakte, is liye waqt poora hone tak dhakkan band rakhein.","Dumpling ko bohat pehle bana lena. Wrapper sookh kar phat jate hain, is liye steam karne se pehle hi shape dein, ya geele kapde se dhak kar rakhein."],"faq":[["Kya bamboo steamer ke baghair dim sum bana sakta hoon?","Ji haan. Metal steamer, pot par colander, ya dhake hue wok mein rack par plate use karein. Achhi tarah line karein taake kuch chipke nahi."],["Mere har gow wrapper kyun phat rahe hain?","Dough sookh gaya, ya zyada thanda ho gaya. Dhak kar rakhein, chhote hisson se kaam karein, aur sakht ho to halka goondh lein."],["Kya frozen prawn use kar sakta hoon?","Ji haan. Poori tarah thaw karein, khushk karein, aur milane se pehle kaatein. Geele prawn se dheeli filling banti hai."],["Dim sum ke sath kaunsi sauce jati hai?","Chilli oil, halki soy sauce aur kaala sirka, zaiqe ke mutabiq milayein. Sirke mein thora kaddukas adrak rawaiti hai."]]},"coqauvin":{"intro":"Coq au vin classic French sukoon wala khana hai, chicken jo laal wine mein halki aanch par pakti hai jab tak haddi se alag na ho jaye, mushroom, pearl piyaz aur bacon ke sath, aisi sauce mein jo wine ka zaiqa deti hai baghair alcoholic lage. Ye Burgundy se hai, jahan wine pakane ka hissa hai, sirf saath peene ke liye nahi, aur lambi halki braise hi chicken ko naram aur sauce ko rich banati hai. Pehle chicken ko achhi tarah brown karein, kyunke wo rang zaiqa ban jata hai, phir pot ko oven mein kaam karne dein. Mashed aalu ya kurkuri roti ke sath serve karein, aur sauce ko aakhir mein namak aur thore makkhan ke sath chakhein taake chamak aaye.","ing":["Chicken thigh","legs 1kg (haddi ke sath)","Laal wine 500ml (mumkin ho to Burgundy style)","Bacon lardon 150g","Mushroom 250g","pearl piyaz 12","Gajar 1","lehsan 3 clove","thyme 3 sprig","Chicken stock 250ml","tomato paste 1 tbsp","Maida 2 tbsp","makkhan 2 tbsp","Serve ke liye parsley","namak","mirch"],"steps":["Chicken ko achhi tarah season karein, halka maida lagayein, aur garam ovenproof pot mein hisson mein brown karein jab tak dono taraf gehri sunehri na ho jaye. Alag rakhein.","Usi pot mein bacon ko kurkura hone tak fry karein, nikaal lein, aur bacon ki charbi mein mushroom aur pearl piyaz ko brown karein.","Gajar, lehsan aur tomato paste daalein, aur 2 minute hilate hue pakayein jab tak khushbu na aaye.","Wine daalein, pot ki teh ko khurach kar sara brown zaiqa uthayein, aur 3 minute simmer karein.","Chicken aur bacon ko wapas pot mein daalein, stock aur thyme daalein, aur halki simmer par le aayein. Liquid chicken ke aadhe tak aana chahiye.","Dhak kar 160C par oven mein 75 se 90 minute pakayein, jab tak chicken bohat naram na ho jaye.","Chicken nikaal lein, aur sauce ko stove par 10 minute simmer karein jab tak chamach par lagne lage. Aakhir mein makkhan phentein.","Chicken ko sauce mein wapas daalein, garam karein, aur parsley chhidak kar serve karein."],"tip":"Braising se pehle chicken ko theek se brown karein. Pheeka chicken pheeki sauce banata hai, jabke gehri sunehri chicken rich, poore zaiqe wali sauce banati hai.","notes":["Haddi wala chicken lambi braise mein juicy rehta hai. Baghair haddi wala chicken jaldi pakta hai aur sookh sakta hai, is liye use karein to oven ka waqt kam karein.","Wo wine use karein jo aap peete. Sasti cooking wine se sakht sauce banti hai, jabke phal jaisi laal wine gehraai aur rang deti hai.","Pearl piyaz chhoti aur meethi hoti hai. Na mile to quarter mein kati hui shallot use karein.","Aakhir mein phenta hua makkhan sauce ko naram chamak deta hai aur wine ko gol kar deta hai. Daalne ke baad sauce ko na ubalein."],"variations":["Safed wine version: khushk safed wine use karein aur aakhir mein cream daalein, halki coq au vin blanc ke liye.","Aalu ke sath: aakhri 40 minute ke liye pot mein chhote naye aalu daalein, taake wo sauce mein pak jayein.","Slow cooker version: pehle sab kuch brown karein, phir low par 5 se 6 ghante pakayein, aur aakhir mein sauce ko stove par gaarha karein."],"serving":"4 logon ke liye hai, uthle piyalon mein, creamy mashed aalu, makkhan wale noodles ya kurkuri roti ke sath taake sauce pakdi jaye. Chicken ko sauce, mushroom aur piyaz ki bhari karchhi ke sath, aur parsley chhidak kar serve karna chahiye. Ye Itwaar ki dish hai, is liye pot se table par serve karein, saath saada green salad aur baaqi wine, agar chahein, glass mein.","storage":"Coq au vin fridge mein 3 din tak rehta hai, aur agle din aur behtar lagta hai. Stove par halki aanch par ubalne tak garam karein, agar sauce zyada gaarhi ho to thora stock daalein. 3 mahine tak achhi tarah freeze hota hai, fridge mein raat bhar rakh kar thaw karein. Chicken ko us ki sauce mein store karein, taake sookh na jaye.","mistakes":["Browning chor dena. Sauce mein rang aur gehraai nahi hogi, is liye hisson mein brown karne ka waqt lein.","Braise ko tez ubalna. Chicken sakht ho jata hai aur sauce jaldi kam ho jati hai, is liye halki simmer aur kam oven rakhein.","Zyada wine aur stock nahi use karna. Sauce tez ho jati hai, is liye wine ko stock se balance karein aur serve karne se pehle chakhein.","Makkhan jaldi daalna. Lambi simmer mein wo phat jata hai, is liye bilkul aakhir mein, ubal se hata kar phentein."],"faq":[["Kya baghair alcohol ke coq au vin bana sakta hoon?","Ji haan, wine ki jagah extra stock aur 2 tbsp laal wine sirka aur thora angoor ka ras use karein. Zaiqa mukhtalif hoga, lekin braise phir bhi kaam karegi."],["Kya chicken breast use kar sakta hoon?","Kar sakte hain, lekin sirf aakhri 30 minute ke liye daalein, warna sookh jayegi. Thigh aur legs is dish ke liye bohat behtar hain."],["Kaunsi wine use karun?","Khushk, phal jaisi laal wine, mumkin ho to Burgundy se. Bohat tannic ya oaky wine se bachein, jo lambi braise mein karwi ho sakti hai."],["Kya pehle se bana sakta hoon?","Ji haan, aur behtar hoti hai. Poori pakayein, thanda karein, fridge mein rakhein, aur agle din halki aanch par garam karein."]]},"bouillabaisse":{"intro":"Bouillabaisse Marseille se hai, jahan machhli pakadne wale un machhliyon se soup banate thay jo bik nahi pati thin, aur ab ye France ki sab se pasandeeda celebration dishes mein se aik hai. Broth star hai, machhli ke stock, tamatar, saunf, orange ke chilke, zafran aur olive oil se banti hai, aur machhli aur shellfish is mein sirf chand minute pakte hain, taake naram rahein. Agar ho sake to do hisson mein serve karein, broth chhan kar piyalon mein aur machhli platter par, rouille ke sath, zafran aur lehsan wali mayonnaise, toasted roti par. Sunne mein grand lagti hai, lekin tareeqa saada hai, achhi broth banayein, machhli ko sahi tartib se daalein, aur zyada na pakayein.","ing":["Mixed sakht safed machhli 800g (tukdon mein kati hui)","Prawn 300g","mussel 300g (saaf ki hui)","Machhli ka stock 1.5 litre","Tamatar 400g (kate hue)","tomato paste 2 tbsp","Saunf 1 bulb","piyaz 1","leek 1","Zafran 1 bari chutki","orange ka chilka 1 strip","Lehsan 4 clove","olive oil 4 tbsp","thyme","Serve ke liye kurkuri roti","rouille","parsley","lemon"],"steps":["Bare pot mein olive oil garam karein, piyaz, leek, saunf aur lehsan ko 8 minute fry karein jab tak naram aur meethi na ho jayein.","Tomato paste aur kate hue tamatar daalein, aur 5 minute pakayein jab tak tamatar tootne na lagein.","Machhli ka stock daalein, zafran, orange ka chilka, thyme aur chutki bhar namak daalein, aur 20 minute simmer karein.","Broth ko chhalni se chhanein, sabziyon ko dabakar sara zaiqa nikalein, phir broth ko wapas pot mein daalein.","Broth ko dobara halki simmer par le aayein, aur sab se sakht machhli pehle daalein, 3 minute pakayein.","Baaqi machhli aur prawn daalein, aur 3 se 4 minute aur pakayein, jab tak pak na jayein.","Mussel daalein, dhak dein, aur 3 minute pakayein jab tak khul na jayein. Jo band rahein unhein phenk dein.","Garam piyalon mein broth aur seafood daalein, aur rouille lagi toasted roti, parsley aur lemon ke sath serve karein."],"tip":"Machhli ko zyada na pakayein. Sab se sakht hisse pehle aur nazuk hisse aakhir mein daalein, aur machhli ke flake hote hi pot ko aanch se utaar lein.","notes":["Zafran mehenga hai, lekin aik chutki broth ko rang aur khushbu se badal deti hai. Daalne se pehle 10 minute garam stock ke aik chamach mein bhigoyein.","Machhli ka mix use karein, jaise monkfish, sea bass aur red mullet agar mil jayein. Sirf aik machhli se soup patla hota hai.","Orange ka chilka roshan, khushbudar note daalta hai jo Marseille mein classic hai. Baghair safed gude ke chaudi strip use karein, aur serve karne se pehle nikaal lein.","Rouille ande ki zardi, lehsan, zafran, lemon aur olive oil ko phent kar mayonnaise banane se banti hai. Zafran wali dukaan ki aioli achha shortcut hai."],"variations":["Clam ke sath: saaf kiye hue clam ko mussel ke sath daalein, aur jo na khulein unhein phenk dein.","Asaan weeknight version: sirf prawn aur aik sakht safed machhli use karein, wohi broth ke sath, aur roti ke sath serve karein.","Aalu ke sath: broth mein kate hue aalu daalein aur machhli daalne se pehle naram hone tak simmer karein, bhari soup ke liye."],"serving":"6 logon ke liye hai, gehre garam piyalon mein, machhli aur shellfish upar sajaye hue, aur rouille wali toast ki plate table ke beech mein. Har shakhs rouille ko broth mein daalta hai ya roti par lagata hai, aur machhli par lemon nichodta hai. Green salad aur aik glass khushk safed wine ke sath serve karein, aur roti aati rahe, kyunke broth chorne ke qabil nahi.","storage":"Bouillabaisse taazi khana behtar hai, usi din jis din bani ho. Sirf broth fridge mein 2 din tak rehti hai aur 1 mahine tak achhi tarah freeze hoti hai. Bachi hui machhli dobara garam karne par achhi nahi rehti aur rubbery ho sakti hai, is liye broth ko alag rakhein aur dobara garam karte hue taazi machhli daalein. Broth ko ubalne tak garam karein, phir is mein taazi seafood pakayein.","mistakes":["Seafood ko zyada pakana. Machhli aur prawn aik minute mein naram se sakht ho jate hain, is liye pot par nazar rakhein.","Chhanne ka step chor dena. Broth chunky rehti hai aur zaiqa kam saaf hota hai, is liye chhanein aur sabziyon ko dabayein.","Oily machhli use karna. Salmon aur mackerel nazuk broth par haawi ho jati hain, is liye sakht safed machhli use karein.","Saari machhli aik sath daalna. Nazuk machhli toot jati hai jab tak sakht machhli pakti hai, is liye stages mein daalein."],"faq":[["Kya dukaan ka machhli stock use kar sakta hoon?","Ji haan. Achhi quality wala stock lein, aur likhe hue tareeqe se sabzi aur zafran ke sath simmer karein. Phir bhi rich lagega."],["Rouille kya hai?","Provence ki zafran aur lehsan wali mayonnaise, toast par lagayi aur soup mein milayi jati hai. Ye richness aur rang daalti hai."],["Kya shellfish ke baghair bouillabaisse bana sakta hoon?","Ji haan, sirf machhli use karein, aur thora extra machhli stock daalein. Soup phir bhi behtareen hoti hai, halanke kam mukhtalif."],["Kya zafran zaroori hai?","Ye classic rang aur khushbu deta hai. Is ke baghair soup phir bhi achhi hoti hai, lekin wo bilkul bouillabaisse nahi hoti."]]},"paella":{"intro":"Paella Spain ke Valencia se hai, jahan ye bahar chaudi uthli pan mein pakai jati hai, aur chawal, seafood nahi, asal star hain. Zafran isay sunehra rang deta hai, achha stock zaiqa deta hai, aur pakane ke aakhri chand minute, baghair hilaye, socarrat banate hain, neeche chawal ki kurkuri toasted teh jis ke liye sab larte hain. Agar mile to chhote dane wala bomba chawal use karein, barabar teh mein phelaein, aur stock daalne ke baad hilane se bachein. Pan mein hi, table ke beech mein, lemon ke sath serve karein, aur har koi ikatha khaye.","ing":["Bomba ya chhote dane wala chawal 400g","Prawn 300g","mussel 300g (saaf ki hui)","Squid ring 200g (optional)","Chicken ya machhli ka stock 1 litre (garam)","Zafran 1 bari chutki","Piyaz 1","laal mirch 1","lehsan 3 clove","Tamatar 2 (kaddukas)","smoked paprika 1 tsp","Olive oil 4 tbsp","lemon 1","matar 100g"],"steps":["Zafran ko 3 tbsp garam stock mein 10 minute bhigoyein, aur baaqi stock garam rakhein.","Chaudi paella pan mein olive oil garam karein, piyaz aur mirch ko 6 minute fry karein jab tak naram na ho jayein, phir lehsan aur paprika daalein.","Kaddukas tamatar daalein aur 4 minute pakayein jab tak gehra aur gaarha na ho jaye.","Chawal daalein aur 1 minute milayein taake sofrito mein lapet jaye, phir barabar teh mein phelaein.","Garam stock aur zafran wala liquid daalein, namak se season karein, aur halke ubal par le aayein. Is ke baad hilayein nahi.","Darmiyani aanch par 15 minute pakayein, phir seafood aur matar ko upar sajayein, halka sa chawal mein dabate hue.","Aanch kam karein, foil se halka dhak dein, aur 10 minute aur pakayein, jab tak chawal naram na ho jaye aur mussel khul na jayein.","Pan ko dhak kar 5 minute rest dein, phir pan mein hi lemon ke sath serve karein, socarrat ki kurkurahat sunte hue."],"tip":"Stock daalne ke baad chawal ko na hilayein. Hilane se starch nikalta hai aur chawal chipchipa ho jata hai, aur socarrat nahi banta.","notes":["Bomba chawal bohat liquid soakh leta hai aur alag rehta hai. Lambe dane wala chawal paella mein naram ho jata hai, is liye bomba na mile to chhote dane wala chawal use karein.","Stock garam rakhein. Thanda stock pan ko thanda kar deta hai aur chawal barabar nahi pakta.","Smoked paprika garam, dhuaan daar note deti hai. Meethi paprika chalti hai, lekin tez paprika zafran par haawi ho sakti hai.","Zafran ko use karne se pehle bhigona chahiye, taake rang aur khushbu chawal mein barabar phele."],"variations":["Chicken aur chorizo paella: sofrito ke sath brown ki hui chicken aur kati hui chorizo daalein, aur chicken stock use karein.","Sabzi paella: sabzi ka stock, artichoke, hari phaliyan aur butter beans use karein, wohi zafran chawal ke tareeqe se.","Mixed paella: chicken, prawn aur mussel milayein, chicken jaldi aur seafood dair se daalte hue, asal tareeqe ke mutabiq."],"serving":"6 logon ke liye hai, pan mein hi table ke beech mein serve ki jati hai, lemon aur green salad ke sath. Har shakhs kinare se andar ki taraf hissa leta hai, taake har kisi ko kurkuri neeche wali teh mile. Paella baant kar khane ki dish hai, is liye extra lemon, kurkuri roti aur aioli rakhein agar chahein, aur kitchen mein alag platon mein serve na karein.","storage":"Paella taazi khana behtar hai, seedha pan se. Bacha hua khana fridge mein 2 din tak rehta hai, aur garam pan mein thore stock ke sath dhak kar steam aane tak dobara garam hota hai. Chawal utna kurkura nahi hoga, aur seafood ko zyada der dobara garam nahi karna chahiye. Shellfish wali paella ko freeze na karein, texture kharab hota hai. Socarrat sirf usi din hota hai.","mistakes":["Chawal ko hilana. Wo chipchipa ho jata hai aur neeche kabhi kurkura nahi hota.","Ghalat chawal use karna. Lambe dane wala chawal aur risotto chawal dono ghalat texture dete hain.","Thanda stock daalna. Pakana ruk ruk kar hota hai, aur chawal barabar nahi pakta.","Pan ko zyada bharna. Upar zyada seafood chawal ko toast hone ke bajaye steam mein paka deta hai, is liye teh barabar aur zyada gehri na rakhein."],"faq":[["Kya paella pan zaroori hai?","Chaudi uthli pan chalti hai, jab tak chawal ki teh patli ho. Gehra pot chawal ko zyada mota kar deta hai aur wo toast hone ke bajaye steam mein pakta hai."],["Kya zafran ke baghair paella bana sakta hoon?","Bana sakte hain, rang ke liye chutki bhar haldi ke sath, lekin zaiqa mukhtalif hoga. Zafran paella ka asal zaiqa hai."],["Kaise maloom karun ke chawal pak gaya?","Chakh kar dekhein. Naram hona chahiye halki si bite ke sath, aur liquid jazb ho jana chahiye. 5 minute rest se mukammal ho jata hai."],["Meri paella naram kyun hai?","Chawal hilaya gaya, stock thanda tha, ya aanch kam thi. Chawal ko baghair hilaye rakhein aur aanch steady rakhein."]]},"beefpho":{"intro":"Pho Vietnam ki sab se mashhoor soup hai, aur is ka dil saaf broth hai jo jale hue piyaz aur adrak, star anise, daarcheeni, laung aur fish sauce ka zaiqa deta hai, beef ki haddiyon ke sath halki aanch par simmer hota hai jab tak rich lekin kabhi ganda na ho jaye. Noodles alag pakte hain, beef ko kagaz ki tarah patla kaata jata hai aur garam broth daalne par pak jata hai, aur piyala table par bean sprout, Thai basil, dhaniya, lime aur mirch ke sath finish hota hai. Is mein waqt lagta hai, lekin kaam zyada tar intezar aur jhaag utaarna hai, aur nateeja aik halka, khushbudar aur gehra sukoon dene wala piyala hai.","ing":["Beef ki haddiyan 1.5kg","marrow ya knuckle haddiyan","Beef brisket ya shin 500g","Chawal noodles 500g (chapte)","Piyaz 2","adrak 1 bara tukda","Star anise 3","daarcheeni 1 stick","laung 4","Dhaniya beej 1 tsp","saunf beej 1 tsp","Fish sauce 4 tbsp","rock sugar 1 tbsp","Serve ke liye bean sprout","Thai basil","dhaniya","lime","mirch"],"steps":["Haddiyon ko ubalte pani mein 5 minute blanch karein, chhanein, dhoein, aur saaf pot mein taaze thande pani ke sath wapas daalein.","Piyaz ke aadhe hisse aur adrak ko khuli aanch ya garam grill par jalayein jab tak jagah jagah kaale na ho jayein, phir pot mein daalein.","Star anise, daarcheeni, laung, dhaniya aur saunf ko khushk pan mein 2 minute toast karein jab tak khushbu na aaye, muslin mein baandhein ya khule daalein aur baad mein chhan lein.","Broth ko bohat halki aanch par 2.5 ghante simmer karein, aksar jhaag utaarte hue, aur brisket ko aakhri 60 minute ke liye daalein jab tak naram na ho jaye.","Brisket nikaal lein, halka thanda karein, patla kaatein, aur broth ko bareek chhalni se chhanein jab tak saaf na ho jaye.","Broth ko fish sauce aur rock sugar se season karein, chakhte hue, jab tak namkeen, khushbudar aur halka meetha na ho jaye.","Chawal noodles ko alag pakayein, chhanein, aur piyalon mein brisket ki slice aur kachhe patle kate beef ke sath baant lein.","Har piyale par ubalti broth daalein, taake kachha beef garmi mein pak jaye, aur herbs, sprout, lime aur mirch ke sath serve karein."],"tip":"Simmer ko halka rakhein aur aksar jhaag utaarein. Tez ubal broth ko ganda aur chikna bana deta hai, jabke khamosh simmer isay saaf aur saaf zaiqe wala rakhta hai.","notes":["Piyaz aur adrak ko jalana dhuaan daar mithaas daalta hai jo pho ke liye zaroori hai. Isay chorain nahi, aur piyaz ko poori tarah na chheelein, chilka rang daalta hai.","Rock sugar fish sauce ko balance karta hai baghair broth ko meetha banaye. Aam cheeni bhi chalti hai, lekin thori kam use karein.","Kachhe beef ko aadha frozen hote hue kaatein. Wo patla aur barabar kata jata hai, aur garam broth mein secondon mein pak jata hai.","Chawal noodles ko bhigona ya naram hone tak pakana chahiye, phir achhi tarah chhana chahiye, taake piyale mein sari broth na soakh lein."],"variations":["Chicken pho: poori chicken aur chicken ki haddiyan use karein, 60 se 75 minute simmer karein, aur gosht ko piyalon ke liye kaat lein.","Vegetarian pho: wohi masalon, jale hue piyaz aur adrak ke sath mushroom aur sabzi ka stock use karein, aur upar tofu aur mushroom rakhein.","Zyada spicy pho: taazi kati hui mirch aur chilli sauce table par daalein, broth mein nahi, taake har shakhs garmi ko control kare."],"serving":"6 logon ke liye hai, gehre piyalon mein, herbs, sprout, lime aur mirch alag piyalon mein table ke beech mein. Har shakhs apni herbs daalta hai aur lime nichodta hai, aur chopsticks aur chamach se khata hai, pehle noodles, phir broth. Pho steam karte hue serve ki jati hai aur foran khai jati hai, jab herbs taazi aur beef abhi paka ho.","storage":"Broth fridge mein 4 din tak rehti hai aur 3 mahine tak achhi tarah freeze hoti hai. Broth, noodles aur topping ko alag rakhein, aur taaza assemble karein. Broth ko ubalne tak garam karein, taaze noodles pakayein, aur serve karne se pehle beef kaatein. Bacha hua paka brisket fridge mein 2 din tak rehta hai. Bhare hue piyale store na karein.","mistakes":["Broth ko tez ubalna. Wo ganda ho jati hai aur charbi soup mein mil jati hai, is liye bareek simmer rakhein.","Jhaag na utaarna. Pot mein rehne wali jhaag aur charbi zaiqa aur saafai ko halka kar deti hai.","Noodles ko zyada pakana. Wo broth soakh lete hain aur naram ho jate hain, is liye alag pakayein aur achhi tarah chhanein.","Seasoning ko chakhna bhool jana. Fish sauce aur cheeni ko aakhir mein balance karna zaroori hai, is liye thori thori miqdar mein season karein aur aksar chakhein."],"faq":[["Kya pressure cooker mein pho bana sakta hoon?","Ji haan. Haddiyon ko pressure par 60 se 75 minute pakayein, phir chhanein aur season karein. Zaiqa bohat qareeb hota hai, halanke broth thori kam saaf hoti hai."],["Kachhi slice ke liye kaunsa beef behtar hai?","Sirloin ya eye of round, aadha frozen hote hue bohat patla kata hua. Wo garam broth mein secondon mein pak jata hai."],["Kya pho gluten free hai?","Chawal noodles aur zyada tar fish sauce qudrati tor par gluten free hote hain, lekin apni fish sauce aur hoisin ke label check karein."],["Kya broth pehle se bana sakta hoon?","Ji haan, aur raat bhar rakhne se behtar hoti hai. Fridge mein rakhein, jammi hui charbi hata dein, aur ubalne tak garam karein."]]},"poutine":{"intro":"Poutine Canada ke Quebec se hai, aur ye shandar tor par saada hai, garam kurkure fries, taaze cheese curd jo kaatne par chikhte hain, aur upar daali gayi rich brown gravy taake curd halke se pighalne lagein. Fries itne kurkure hone chahiye ke gravy ko baghair aik minute mein geela hue sambhal sakein, is liye do dafa fry karna qabil hai, aur gravy bohat garam honi chahiye, kyunke garmi hi curd ko naram karti hai. Foran serve karein, piyale mein, kaante ke sath, aur khayein jab fries kinaron par kurkure aur gravy neeche jama ho rahi ho.","ing":["Aalu 1kg (floury qism)","Cheese curd 250g (room temperature par)","Beef ya sabzi ka stock 500ml","Makkhan 2 tbsp","maida 2 tbsp","Soy sauce 1 tsp","Worcestershire sauce 1 tsp","Lehsan 1 clove","kaali mirch","Deep fry ke liye oil","namak","Serve ke liye hari piyaz (optional)"],"steps":["Aalu ko mote baton mein kaatein, thande pani mein 30 minute bhigoyein, phir chhanein aur bohat achhi tarah khushk karein.","Oil ko 160C tak garam karein, chips ko hisson mein 5 se 6 minute fry karein jab tak halke aur naram na ho jayein, phir chhan kar 10 minute rest dein.","Chips rest karte hue, pan mein makkhan pighlayein, maida milayein, aur 2 minute pakayein jab tak halka sunehra na ho jaye.","Garam stock ko thora thora kar ke phentein, phir soy, Worcestershire, lehsan aur mirch daalein, aur 5 minute simmer karein jab tak naram aur chamakdar na ho jaye.","Oil ko 190C tak garam karein, aur chips ko dobara hisson mein 2 se 3 minute fry karein jab tak gehre sunehre aur bohat kurkure na ho jayein. Chhan kar foran namak daalein.","Garam chips ko garam piyalon mein daalein, upar cheese curd bikhrein, aur curd ko room temperature par rakhein taake wo pighle baghair naram hon.","Upar se bohat garam gravy daalein, taake wo khaali jagah mein jaye aur curd ko pighlana shuru kare.","Kaante ke sath foran serve karein, agar chahein to upar hari piyaz daal kar, aur garam khayein."],"tip":"Cheese curd ko room temperature par use karein. Thande curd sakht rehte hain aur naram nahi hote, jabke room temperature wale curd garam gravy ke neeche naram aur chikne ho jate hain.","notes":["Floury aalu sab se fluffy chips banate hain. Waxy aalu dense rehte hain aur usi tarah kurkure nahi hote.","Cheese curd taaze aur chikne hone chahiye. Agar curd na mile to taazi mozzarella ke tukde use karein, halanke chikh nahi hogi.","Gravy itni patli honi chahiye ke beh sake, stew jaisi gaarhi nahi. Thandi hote hi gaarhi ho jati hai, is liye bohat garam serve karein.","Do dafa fry karna kurkure chips ka raaz hai jo dair tak rehte hain. Pehli fry andar pakati hai, dosri fry bahar kurkura karti hai."],"variations":["Pulled pork ke sath: upar halki aanch par paka pulled pork aur extra gravy daalein, bhari main course ke liye.","Mushroom ke sath: gravy mein fry ki hui mushroom aur thyme daalein, aur sabzi ka stock use karein, vegetarian version ke liye.","Nashta poutine: upar aik fried anda daalein, aur saath bacon serve karein."],"serving":"4 logon ke liye hai, snack, side, ya sharing main course ke tor par, gehre piyalon mein kaanton ke sath. Gravy daalte hi serve karein, jab chips kurkure aur curd naram ho rahe hon, aur baitha rehne na dein, kyunke chips jaldi naram ho jate hain. Poutine casual khana hai, is liye table ke beech mein serve karein, aur zyada gravy jug mein rakhein jo chahe. ","storage":"Poutine taazi khana behtar hai aur milane ke baad dobara garam karne par achhi nahi rehti, kyunke chips naram ho jate hain. Hisson ko alag rakhein, chips, curd aur gravy, fridge mein 2 din tak. Chips ko garam oven mein kurkura hone tak dobara garam karein, gravy ko ubalne tak garam karein, aur taaza assemble karein. Sirf gravy 1 mahine tak achhi tarah freeze hoti hai.","mistakes":["Thande cheese curd use karna. Wo sakht rehte hain aur fries mein nahi pighalte.","Neem garam gravy daalna. Wo curd ko naram nahi karti, is liye gravy ko steam nikalne tak garam karein.","Chips ko sirf aik dafa fry karna. Wo chand minute mein gravy ke neeche naram ho jate hain, is liye do dafa fry karein.","Dosri fry se pehle chips par namak daalna. Namak pani nikalta hai aur kurkura hone se rokta hai, is liye sirf aakhir mein namak daalein."],"faq":[["Cheese curd kya hain?","Doodh ke jamne ke taaze tukde, halke se dabaye hue, kaatne par chikhne wali texture ke sath. Ye poutine ka asal ingredient hain."],["Kya frozen chips use kar sakta hoon?","Ji haan. Oven ya air fryer mein bohat kurkura hone tak pakayein, phir garam gravy aur curd ke sath assemble karein. Taaze chips ko do dafa fry karna behtar hai, lekin frozen chips bhi chalte hain."],["Kya poutine vegetarian hai?","Sabzi ke stock aur vegetarian Worcestershire sauce ke sath ho sakti hai. Rawaiti gravy mein beef stock hota hai, is liye apna stock check karein."],["Kya gravy pehle se bana sakta hoon?","Ji haan. 3 din pehle tak bana kar fridge mein rakhein, aur chips par daalne se pehle ubalne tak garam karein."]]},"bobotie":{"intro":"Bobotie South Africa ki pasandeeda baked qeema dish hai, Cape Malay pakane ki jadein rakhti hai, jahan masaledar qeeme ko phal se meetha kiya jata hai, bhigoi hui roti se rich banaya jata hai, aur tez patton ke sath sunehri ande ki custard topping ke neeche bake kiya jata hai. Zaiqa garam aur halka meetha hota hai, curry powder, haldi, chutney, kishmish aur khoobani sab mil kar kaam karte hain, aur texture naram aur sukoon dene wala hota hai. Peele chawal, chutney aur saada salad ke sath serve karein, aur meetha aur namkeen balance ko bolne dein. Bheed ke liye pehle se banane ki behtareen dish hai, kyunke dobara garam karne par khoobsurat rehti hai aur agle din aur behtar lagti hai.","ing":["Beef ya lamb qeema 750g","Piyaz 1","lehsan 2 clove","adrak 1 tsp","Curry powder 2 tbsp","haldi 1 tsp","Safed roti 2 slice","doodh 250ml","Ande 3","tez patte 4","Chutney 3 tbsp","kishmish 3 tbsp","Sookhi khoobani 4 (kati hui)","lemon juice 1 tbsp","Badam 2 tbsp (flaked)","namak","mirch"],"steps":["Roti ko 125ml doodh mein bhigoyein jab tak naram na ho jaye, phir extra doodh nikaal kar roti ko chura kar lein.","Piyaz, lehsan aur adrak ko oil mein 5 minute fry karein jab tak naram na ho jayein, phir curry powder aur haldi daal kar 1 minute fry karein.","Qeema daalein aur tootte hue fry karein, jab tak har taraf brown na ho jaye aur liquid pak na jaye.","Bhigoi hui roti, chutney, kishmish, khoobani, lemon juice aur seasoning milayein, aur 5 minute pakayein. Chakhein aur meetha khatta balance theek karein.","Qeeme ko makkhan lagi baking dish mein daalein, barabar dabayein, aur tez patte upar laga dein.","Baaqi doodh ko 2 andon aur chutki bhar namak ke sath phentein, aur qeeme par halke se daalein.","180C par 35 se 40 minute bake karein, jab tak topping set aur sunehri na ho jaye, aur kinare bulbule na banane lagein.","10 minute rest dein, flaked badam chhidkein, aur peele chawal aur extra chutney ke sath serve karein."],"tip":"Bake karne se pehle qeeme ko chakhein. Meetha, khatta aur spicy balance is stage par theek hona chahiye, kyunke bake karne se theek nahi hoga.","notes":["Bhigoi hui roti qeeme ko naram aur halka rakhti hai. Is ke baghair bobotie dense aur khushk ho sakti hai.","Curry powder bohat mukhtalif hota hai. Agar mile to halka Cape Malay style curry powder use karein, aur chakhne ke baad hi zyada daalein.","Chutney mithaas aur khattapan daalti hai. Phal wali chutney rawaiti hai, aur aam ki chutney bhi achhi chalti hai.","Tez patte upar lagte hain, milaye nahi jate, taake wo custard ko zaiqa dein aur serve karte hue khoobsurat lagein."],"variations":["Masoor ke sath: aadha qeema paki hui brown masoor se badlein, halki version ke liye wohi masalon ke sath.","Vegetarian bobotie: wohi phal, chutney aur ande ki topping ke sath masoor aur mushroom use karein.","Zyada spicy version: piyaz ke sath 1 kati hui taazi mirch daalein, aur saath extra chutney aur sambal serve karein."],"serving":"6 logon ke liye hai, peele chawal, phal wali chutney aur kurkuri green salad ya kate hue tamatar aur piyaz ki salad ke sath. Baking dish se seedha, bare square mein serve karein, sunehri topping aur har hisse par aik tez patta ke sath. Bobotie family dish hai, is liye dish ko table ke beech mein rakhein, chawal aur chutney ke saath, aur har koi khud le.","storage":"Bobotie fridge mein dhak kar 3 din tak rehti hai, aur 160C par oven mein garam hone tak achhi tarah dobara garam hoti hai. 3 mahine tak achhi tarah freeze hoti hai, fridge mein raat bhar rakh kar thaw karein. Ande ki topping dobara garam karne par thora pani chor sakti hai, is liye halki aanch par aur foil se dhak kar garam karein. Peela chawal alag se 2 din tak rehta hai.","mistakes":["Baghair roti ke bohat lean qeema use karna. Wo khushk aur tootne wala ho jata hai, is liye bhigoi hui roti rakhein.","Topping ko zyada bake karna. Wo rubbery ho jati hai, is liye set aur sunehri hote hi nikaal lein.","Rest chor dena. Bobotie garam kaatne par toot jati hai, is liye serve karne se pehle 10 minute rest dein.","Zyada meetha bana dena. Qeeme ko chakhein, aur chutney aur phal ko lemon juice se balance karein, zyada cheeni se nahi."],"faq":[["Kya bobotie pehle se bana sakta hoon?","Ji haan. Poori assemble kar ke 1 din tak fridge mein rakhein, aur zaroorat par bake karein, bake ke waqt mein 10 minute aur daal kar."],["Kya bobotie spicy hai?","Ye garam masaledar hai, tez nahi. Curry powder zaiqa deta hai, aur phal aur chutney isay halka rakhte hain."],["Peela chawal kya hai?","Haldi, kishmish aur kabhi kabhi daarcheeni ke sath paka chawal, South Africa mein bobotie ke sath serve hota hai. Saada chawal bhi chalta hai."],["Kya lamb qeema use kar sakta hoon?","Ji haan. Lamb se zyada rich bobotie banti hai. Brown karne ke baad extra charbi nikaal lein, taake bake chikna na ho."]]},"moussaka":{"intro":"Moussaka Greece ki azeem layered bake hai, naram baingan, daarcheeni ki khushbu wala rich tamatar aur lamb ya beef qeema sauce, aur mote bechamel ki topping jo oven mein sunehri ho jati hai. Is mein thora waqt lagta hai, kyunke har teh assemble karne se pehle alag pakai jati hai, lekin yehi is ki structure aur zaiqa deta hai, aur pehle se bana kar rest dena behtar hai, taake teh set ho jayein aur saaf slice hon. Garam serve karein, square mein, saada salad ke sath, aur rest ke waqt mein jaldi na karein. Ye Itwaar ki dish hai, generous aur sukoon dene wali, aur table ko khushi se khilati hai.","ing":["Baingan 2 bare (kate hue)","Aalu 3 (kate hue, optional)","Lamb ya beef qeema 600g","Piyaz 1","lehsan 3 clove","Tamatar 400g (kate hue)","tomato paste 2 tbsp","Daarcheeni 1 tsp","oregano 1 tsp","jaiphal","Doodh 500ml","makkhan 50g","maida 50g","ande 2","Cheese 80g (kaddukas)","kefalotyri ya parmesan"],"steps":["Baingan ki slice par namak daalein aur 30 minute rest dein, phir khushk karein aur sunehra aur naram hone tak fry ya roast karein. Alag rakhein.","Aalu ki slice ko halka naram hone tak ubalein ya roast karein, agar use kar rahe hon, aur alag rakhein.","Piyaz aur lehsan ko naram hone tak fry karein, qeema daalein, aur achhi tarah brown karein, tootte hue.","Tomato paste, kate hue tamatar, daarcheeni, oregano aur seasoning daalein, aur 20 minute simmer karein jab tak gaarha na ho jaye.","Makkhan pighla kar, maida mila kar, aur garam doodh phent kar bechamel banayein jab tak gaarha aur naram na ho jaye. Halka thanda karein, phir ande aur aadhi cheese phentein.","Makkhan lagi baking dish mein aalu, phir baingan, phir qeema sauce ki teh lagayein, aik dafa dohraein, aur bechamel se finish karein.","Baaqi cheese aur thora jaiphal chhidkein, aur 180C par 40 se 45 minute bake karein jab tak sunehra aur bulbule wala na ho jaye.","Kaatne se pehle 20 minute rest dein, taake teh set ho jayein, aur salad ke sath garam serve karein."],"tip":"Kaatne se pehle moussaka ko rest dein. Oven se garam nikal kar wo toot jati hai, rest karne par saaf, khoobsurat tehon mein katti hai.","notes":["Baingan par namak daalne se karwa pani nikal jata hai aur wo zyada oil nahi soakhta. Fry karne se pehle khushk karein.","Daarcheeni Greek qeema sauce ka asal masala hai. Halka use karein, taake sauce ko garam kare baghair meetha lage.","Bechamel itni gaarhi honi chahiye ke upar baith sake. Agar patli ho to qeeme mein doob jati hai, is liye chamach par lagne tak pakayein.","Cheese ko bareek kaddukas karein taake bechamel mein barabar pighle aur upar achhi tarah brown ho."],"variations":["Vegetarian moussaka: qeeme ki jagah masoor aur mushroom use karein, wohi masale aur bechamel rakhte hue.","Courgette ke sath: baingan ke sath roast ki hui courgette ki teh daalein, extra sabzi ke liye.","Halki version: baingan ko fry karne ke bajaye roast karein, aur bechamel ke liye semi skimmed doodh use karein."],"serving":"6 logon ke liye hai, bare square mein, tamatar, kheera, piyaz aur zaitoon ki saada Greek salad, aur saath kurkuri roti ke sath. Garam serve karein, bohat garam nahi, taake zaiqe settle ho jayein aur teh qaim rahein. Moussaka baant kar khane ki dish hai, is liye baking dish ko table par layein, aur zyada salad aur roti ke sath serve karein jo chahe.","storage":"Moussaka fridge mein dhak kar 3 din tak rehti hai, aur 160C par oven mein garam hone tak achhi tarah dobara garam hoti hai. Hisson mein 3 mahine tak achhi tarah freeze hoti hai, fridge mein raat bhar rakh kar thaw karein. Foil se dhak kar dobara garam karein taake upar zyada brown na ho. Poori dish ko microwave na karein, bechamel phat sakti hai.","mistakes":["Baingan par namak daalna chor dena. Wo karwa rehta hai aur oil soakh leta hai, jis se bake chikna ho jata hai.","Patli bechamel banana. Wo doob jati hai aur upar kabhi sunehra set nahi hota.","Jaldi kaatna. Teh phisal jati hain, is liye kam az kam 20 minute rest dein.","Qeema sauce ko kam pakana. Pani wali sauce bake ko geela bana deti hai, is liye gaarha hone tak simmer karein."],"faq":[["Kya moussaka pehle se bana sakta hoon?","Ji haan, aur pehle se banana behtar hai. Assemble kar ke 1 din tak fridge mein rakhein, aur zaroorat par bake karein, 10 minute aur daal kar."],["Kya lamb ki jagah beef use kar sakta hoon?","Ji haan. Beef se halki moussaka banti hai. Lamb rawaiti aur zyada rich hai, is liye apni pasand chunein."],["Kya moussaka gluten free hai?","Likhe hue tareeqe se nahi, kyunke bechamel mein maida hai. Bechamel ke liye gluten free maida blend use karein, aur apna stock check karein."],["Meri bechamel dana daar kyun hai?","Doodh jaldi daala gaya, ya maida nahi paka. Musalsal phentein, garam doodh aahista daalein, aur naram hone tak pakayein."]]},"hummus":{"intro":"Achha hummus texture ke bare mein hai, silky, halka aur whipped, kabhi dana daar ya bhari nahi. Ye Levant se hai, jahan chane, tahini, lemon aur lehsan ko barf wale pani ke sath blend kiya jata hai jab tak dip halki aur fluffy na ho jaye, phir olive oil, paprika aur poore chane ke sath finish kiya jata hai. Raaz hai tahini ko pehle, akele blend karna, jab tak poori tarah naram na ho jaye, aur sab se naram nateeje ke liye garam chane, ya chilke utaare hue chane use karna. Mezze spread ke hisse ke tor par serve karein, garam pitta, zaitoon aur salad ke sath, aur har koi scoop kar ke baant le.","ing":["Chane 400g (pake hue, chhane hue)","Tahini 120g (achhi tarah hilayi hui)","Lemon juice 3 tbsp","lehsan 1 chhota clove","Barf wala pani 4 se 6 tbsp","Olive oil 2 tbsp (aur serve ke liye zyada)","Namak 1 tsp","zeera 1/2 tsp (optional)","Serve ke liye paprika","parsley","Serve ke liye garam pitta roti"],"steps":["Agar tin wale chane use kar rahe hon to unhein apne liquid mein 5 minute garam karein, chhanein, aur thora liquid bacha lein. Waqt ho to dheele chilke utaar lein.","Tahini, lemon juice, lehsan aur namak ko 2 minute blend karein jab tak bohat naram, halki aur halki fluffy na ho jaye.","Garam chane daalein aur 3 se 4 minute blend karein, kinaron ko khurachte hue, jab tak poori tarah naram na ho jaye.","Barf wala pani aik chamach kar ke daalein, har dafa blend karte hue, jab tak hummus halka, whipped aur scoop karne ke qabil naram na ho jaye.","Chakhein aur lemon, namak aur lehsan ko theek karein. Wo roshan aur namkeen hona chahiye, tahini ke zaiqe ke sath, tez nahi.","Uthle piyale mein daalein, upar chamach ke peeche se ghumayein, aur olive oil daalein.","Upar chand poore chane, chutki bhar paprika aur kati hui parsley daalein.","Room temperature par garam pitta, sabzi ki sticks aur zaitoon ke sath serve karein."],"tip":"Tahini ko pehle blend karein, chane se pehle. Akele blend ki hui tahini halki aur creamy ho jati hai, aur yehi hummus ko silky banata hai.","notes":["Tahini ki quality sab se zyada ahm hai. Chhilke utaare hue til se bani behne wali, achhi tarah hilayi hui tahini use karein. Moti, khushk tahini se bhari hummus banti hai.","Barf wala pani hummus mein hawa phenta hai aur oil daale baghair dheela karta hai. Aahista daalein, warna hummus behne lagti hai.","Lehsan chhota aur taaza hona chahiye. Aik bara kachha clove poore piyale par haawi ho sakta hai, is liye kam se shuru karein.","Garam chane thande chanon se zyada naram blend hote hain, kyunke un ka starch naram hota hai. Thande chane use karein to pehle garam karein."],"variations":["Roasted laal mirch hummus: 1 roasted laal mirch blend karein, aur lemon thora kam karein.","Chukandar hummus: rang aur mithaas ke liye 1 chhota paka hua chukandar blend karein, khoobsurat gulabi version.","Spicy hummus: tahini ke sath 1 tsp harissa ya chilli paste daalein, aur upar chilli oil daalein."],"serving":"6 logon ke liye hai, mezze spread ke hisse ke tor par, garam pitta, zaitoon, achar, salad aur dosri dip ke sath. Hummus ko chaudi uthli piyale mein serve karein, ghumao mein olive oil jama hua, aur har koi pitta phaad kar scoop kare. Sandwich spread, roasted sabzi ki base, ya grilled gosht aur falafel ke saath side ke tor par bhi behtareen hai.","storage":"Hummus fridge mein airtight dabbe mein 4 din tak rehti hai, upar olive oil ki patli teh ke sath. Serve karne se pehle room temperature par le aayein, aur achhi tarah hilayein. 3 mahine tak achhi tarah freeze hoti hai, fridge mein raat bhar rakh kar thaw karein, phir dobara naram phentein. 2 ghante se zyada room temperature par na chorain.","mistakes":["Sab kuch aik sath blend karna. Tahini kabhi naram nahi hoti, is liye pehle akele blend karein.","Thande, khushk chane use karna. Wo dana daar blend hote hain, is liye garam karein aur barf wala pani aahista daalein.","Zyada lehsan daalna. Kachha lehsan hummus ke baithne par tez ho jata hai, is liye kam use karein aur chakhein.","Seedha fridge se serve karna. Thandi hummus sakht aur pheeki hoti hai, is liye pehle garam hone dein."],"faq":[["Kya sookhe chane use kar sakta hoon?","Ji haan. Raat bhar bhigoyein, chutki bhar bicarbonate of soda ke sath bohat naram hone tak pakayein, aur garam use karein. Wo sab se naram hummus dete hain."],["Meri hummus dana daar kyun hai?","Tahini pehle blend nahi hui, chane thande thay, ya chilke reh gaye. Zyada der blend karein aur barf wala pani daalein."],["Kya tahini ke baghair hummus bana sakta hoon?","Bana sakte hain, extra olive oil aur thore sesame oil ke sath, lekin wo classic hummus jaisa zaiqa nahi dega. Tahini dish ka dil hai."],["Kya hummus sehatmand hai?","Ye chane, tahini, lemon aur olive oil se banti hai, yahan koi number nahi diye gaye. Oil aur namak wo hisse hain jin par nazar rakhein, is liye sabzi aur pitta ke sath serve karein."]]},"falafel":{"intro":"Asli falafel kachhe bhigoye hue chanon se banti hai, kabhi tin wale ya pake hue chanon se nahi, aur yehi isay halka, fluffy andar aur kurkuri, khurdari crust deti hai. Chane ko piyaz, lehsan, parsley, dhaniya aur zeere ke sath mota peesa jata hai, rest diya jata hai taake mix qaim rahe, phir shape diya jata hai aur gehra sunehra hone tak fry kiya jata hai. Garam pitta mein salad aur tahini sauce ke sath serve karein, ya mezze spread ke hisse ke tor par hummus ke sath. Mix pehle se bana kar thanda kiya ja sakta hai, aur falafel chand minute mein fry ho jati hai, is liye bheed ke liye behtareen hai, jab tak pan ko bharain nahi.","ing":["Sookhe chane 250g (raat bhar bhigoye hue)","Piyaz 1","lehsan 3 clove","Parsley 1 bara bunch","dhaniya 1 bunch","Zeera 2 tsp","dhaniya powder 1 tsp","Baking powder 1/2 tsp","maida 2 tbsp","Namak 1 tsp","kaali mirch","chilli flakes","Fry ke liye oil","Serve ke liye pitta","salad","tahini sauce"],"steps":["Chanon ko bohat se thande pani mein raat bhar bhigoyein, phir bohat achhi tarah chhanein. Pakayein nahi.","Chane, piyaz, lehsan, herbs, masale, namak aur mirch ko food processor mein daalein, aur mota aur crumbly hone tak pulse karein, paste nahi.","Piyale mein daalein, maida aur baking powder milayein, dhak kar fridge mein 30 minute rakhein taake sakht ho jaye.","Pehle aik falafel test karein, chhoti ball banayein, fry karein, aur check karein ke qaim rehti hai aur andar tak pakti hai.","Baaqi ko geele haathon se chhoti ball ya patties mein shape dein, akhrot ke size ki.","Oil ko 175C tak garam karein, aur hisson mein 3 se 4 minute fry karein, aik dafa palat kar, jab tak gehra sunehra aur kurkura na ho jaye.","Wire rack par chhanein, kagaz par nahi, taake crust kurkuri rahe, aur thora namak chhidkein.","Pitta mein salad, tamatar, kheera aur tahini sauce ke sath garam serve karein, ya hummus ke sath mezze plate par."],"tip":"Kachhe bhigoye hue chane use karein, kabhi pake hue chane nahi. Pake hue chane se naram, mushy falafel banti hai jo oil mein toot jati hai.","notes":["Raat bhar bhigona zaroori hai. Kam bhige hue chane andar sakht rehte hain, is liye thande pani mein poore 12 ghante dein.","Pulse karein, puree nahi. Herb ke nazar aane wale tukdon ke sath moti texture falafel ko halka, fluffy bite deti hai.","Mix ko thanda karna shape qaim rakhne mein madad karta hai. Agar geela lage to aik chamach maida daalein, lekin zyada na daalein warna falafel bhari ho jati hai.","Oil ka temperature ahm hai. Bohat thanda ho to falafel oil soakh leti hai, bohat garam ho to bahar brown ho jati hai andar kachhi rehte hue."],"variations":["Baked falafel: oil brush kar ke 200C par 20 se 25 minute bake karein, aik dafa palat kar, halki version ke liye.","Broad beans ke sath: aadhe chane ko bhigoi hui split broad beans se badlein, Egyptian style taameya ke liye.","Spicy falafel: mix mein 1 kati hui taazi mirch aur extra zeera daalein, aur chilli sauce ke sath serve karein."],"serving":"4 logon ke liye hai, har shakhs ke liye 4 se 5 falafel, garam pitta mein salad aur tahini ke sath, ya mezze spread ke hisse ke tor par. Oil se nikalte hi serve karein, jab crust kurkuri aur andar garam aur fluffy ho, lemon aur extra tahini ke sath. Falafel haath se khane wala khana hai, is liye khoob pitta, salad aur sauce rakhein, aur har koi apni khud banaye.","storage":"Kachha falafel mix fridge mein dhak kar 2 din tak rehta hai. Paki hui falafel fridge mein 2 din tak rehti hai, aur garam oven mein kurkura hone tak dobara garam hoti hai, taqreeban 8 minute. Microwave na karein, wo naram ho jati hai. Kachhi shape di hui falafel 1 mahine tak achhi tarah freeze hoti hai, frozen se aik minute zyada fry karein.","mistakes":["Tin wale chane use karna. Wo pehle se pake hue hote hain, is liye falafel mushy ho kar toot jati hai.","Mix ko zyada process karna. Naram paste se dense, bhari falafel banti hai, is liye halka pulse karein aur mota rakhein.","Bohat thande oil mein fry karna. Falafel oil soakh leti hai aur chikni ho jati hai, is liye pehle oil ko theek se garam karein.","Bohat bara shape dena. Bari falafel andar kachhi rehti hai, is liye akhrot ke size ki rakhein."],"faq":[["Kya falafel ko fry karne ke bajaye bake kar sakta hoon?","Ji haan. Wo kam kurkuri hoti hai, lekin phir bhi mazedar hoti hai. Oil brush karein, 200C par bake karein, aur aadhe waqt mein aik dafa paltein."],["Meri falafel kyun toot gayi?","Mix zyada geela tha, ya oil zyada thanda tha. Mix ko thanda karein, thora maida daalein, aur pehle aik test karein."],["Kya maida daal kar tin wale chane use kar sakta hoon?","Recommend nahi kiya jata. Maide ke sath bhi pake hue chane se dense falafel banti hai. Bhigoye hue kachhe chane zaroori hain."],["Falafel ke sath kaunsi sauce jati hai?","Lemon aur pani se patli ki hui tahini sauce, aur pitta mein salad. Chilli sauce aur achar bhi rawaiti hain."]]},"feijoada":{"intro":"Feijoada Brazil ki qomi dish hai, aik rich kaale beans ka stew, pork, sausage aur smoked gosht ke mix ke sath, halki aanch par pakaya jata hai jab tak beans creamy aur gosht naram na ho jaye. Rawaiti tor par Hafta ko serve ki jati hai, lambi family lunch ke tor par, safed chawal, saute ki hui collard greens, farofa, toasted cassava aata, aur orange ki slice ke sath taake richness kam ho. Is mein waqt lagta hai, aur ye bheed ko khilati hai, is liye bara pot pakayein, saath wali cheezein saada rakhein, aur khane ko lamba chalne dein. Beans ko raat bhar bhigoyein, gosht ko achhi tarah brown karein, aur pot ko lambi, halki simmer dein, aur nateeja gehra sukoon dene wala hota hai.","ing":["Sookhe kaale beans 500g (raat bhar bhigoye hue)","Pork shoulder 500g (cube mein kata hua)","Smoked sausage 300g (slice mein kati hui)","Bacon ya salt pork 200g (dice mein kata hua)","Piyaz 1","lehsan 4 clove","Tez patte 3","zeera 1 tsp","oregano 1 tsp","Orange 1 (serve ke liye)","chawal","collard greens (Farofa ya toasted breadcrumb serve ke liye, optional)"],"steps":["Beans ko raat bhar thande pani mein bhigoyein, chhanein, aur dhoein.","Pork, sausage aur bacon ko bare pot mein hisson mein brown karein, phir alag rakhein, charbi pot mein rakhte hue.","Usi pot mein piyaz aur lehsan ko naram hone tak fry karein, phir zeera aur oregano daalein.","Gosht ko wapas pot mein daalein, beans, tez patte aur 3cm dhakne ke liye kaafi pani daalein.","Ubal le aayein, jhaag utaarein, phir bohat halki simmer par, aadha dhak kar, 2 se 2.5 ghante pakayein.","Kabhi kabhi hilayein, zaroorat par garam pani daalte hue, jab tak beans creamy aur gosht naram na ho jaye.","Chakhein aur namak aur mirch se season karein. Gosht namak daalta hai, is liye zyada daalne se pehle chakhein.","Gehre piyalon mein safed chawal, saute ki hui collard greens, farofa aur orange ki slice ke sath serve karein."],"tip":"Beans ko raat bhar bhigoyein aur halki aanch par simmer karein. Jaldi wale beans sakht rehte hain, aur tez ubal unhein creamy beans ke bajaye mush mein tod deta hai.","notes":["Kaale beans zaroori hain. Wo creamy aur gehre ho jate hain, aur poore stew ko rang dete hain. Kidney beans se mukhtalif dish banti hai.","Gosht ka mix feijoada ko gehraai deta hai. Jo mile use karein, lekin classic zaiqe ke liye kuch smoked zaroor rakhein.","Tez patte serve karne se pehle nikaal lein. Wo stew ko zaiqa dete hain, lekin khane mein achhe nahi lagte.","Orange ki slice sajawat nahi hain. Un ka khattapan pork aur beans ki richness ko kaat ta hai, is liye khoob serve karein."],"variations":["Chicken ke sath: aadha pork chicken thigh se badlein, aakhri 45 minute ke liye daalte hue, halki version ke liye.","Vegetarian feijoada: sabzi ke stock ke sath mushroom, smoked tofu aur extra beans use karein, wohi seasoning rakhte hue.","Pressure cooker version: bhigoye hue beans aur gosht ko pressure par 35 minute pakayein, phir gaarha karne ke liye 15 minute baghair dhake simmer karein."],"serving":"8 logon ke liye hai, lambi family lunch ke tor par, safed chawal, lehsan ke sath saute ki hui collard greens, farofa aur orange ki slice table ke beech mein. Har shakhs chawal par beans aur gosht serve karta hai, greens aur farofa daalta hai, aur munh taaza karne ke liye bite ke darmiyan orange khata hai. Thande drink ke sath serve karein aur pot ko stove par rakhein, kyunke dosri dafa lena expected hai.","storage":"Feijoada fridge mein 4 din tak rehti hai, aur raat bhar rakhne se zaiqa behtar ho jata hai. Halki aanch par ubalne tak garam karein, agar gaarhi ho gayi ho to thora pani daalein. Hisson mein 3 mahine tak bohat achhi tarah freeze hoti hai, fridge mein raat bhar rakh kar thaw karein. Chawal, greens aur farofa taaze banayein, ya alag se 2 din tak rakhein.","mistakes":["Raat bhar bhigona chor dena. Beans ko zyada waqt lagta hai aur barabar nahi pakte.","Tez ubalna. Beans toot jate hain aur stew mushy ho jata hai, is liye halki simmer rakhein.","Namak jaldi daalna. Namak beans ko sakht kar sakta hai, is liye chakhne ke baad aakhir mein achhi tarah season karein.","Saath wali cheezon ke baghair serve karna. Chawal, greens, farofa aur orange dish ka hissa hain, extra nahi."],"faq":[["Kya tin wale kaale beans use kar sakta hoon?","Ji haan, mushkil mein. Brown kiye hue gosht ke sath aakhri 30 minute ke liye daalein, aur pani kam karein, lekin stew kam rich hoga."],["Kya feijoada bohat fatty hai?","Ye rich stew hai, pork aur sausage se bana. Halki version ke liye lean cut use karein aur brown karne ke baad extra charbi nikaal lein."],["Farofa kya hai?","Toasted cassava aata, aksar piyaz aur bacon ke sath, beans aur chawal par chhidka jata hai. Toasted breadcrumb achha badal hai."],["Kya feijoada pehle se bana sakta hoon?","Ji haan, aur agle din behtar hoti hai. Poori pakayein, thanda karein, fridge mein rakhein, aur halki aanch par garam karein."]]},"meatpie":{"intro":"Aussie meat pie aik icon hai, haath mein pakda jane wala, sunehra aur Australia bhar mein football game, bakery aur kitchen table par khaya jane wala. Kurkuri shortcrust base aur flaky puff pastry lid ke andar rich beef filling hoti hai, piyaz, tamatar, Worcestershire sauce aur thori Vegemite ke sath halki aanch par pakai hui, itni gaarhi ke pie kaatne par shape qaim rahe, lekin itni juicy ke upar tomato sauce chahiye. Filling ko pehle bana kar poori tarah thanda karein, kyunke garam filling pastry ko pighla deti hai, phir lid ke gehra sunehra hone tak bake karein. Garam serve karein, tomato sauce ke sath, aur haathon se khayein, Australian tareeqe se.","ing":["Beef chuck 700g (chhote dice mein kata hua)","Piyaz 1","lehsan 2 clove","Tomato paste 2 tbsp","beef stock 400ml","Worcestershire sauce 2 tbsp","Vegemite 1 tsp","Maida 2 tbsp","thyme 1 tsp","Base ke liye shortcrust pastry","lid ke liye puff pastry","Anda 1 (phenta hua, glaze ke liye)","Serve ke liye tomato sauce","namak","mirch"],"steps":["Beef ko garam pot mein hisson mein brown karein, phir alag rakhein. Usi pot mein piyaz aur lehsan ko brown karein.","Tomato paste aur maida daalein, 1 minute pakayein, phir stock daal kar hilayein taake brown zaiqa uth jaye.","Beef ko wapas daalein, Worcestershire, Vegemite aur thyme daalein, aur 60 se 75 minute halki aanch par simmer karein jab tak naram aur gaarha na ho jaye.","Filling ko poori tarah thanda karein, mumkin ho to fridge mein. Garam filling pastry ko pighla degi aur geela bana degi.","Grease ki hui pie tin ya muffin tin ko shortcrust pastry se line karein, thandi beef filling se bharein, aur kinaron par anda brush karein.","Upar puff pastry lid lagayein, kinaron ko daba kar band karein, kaat lein, aur har lid mein chhota steam hole kaatein.","Phente hue ande se brush karein, aur 200C par 25 se 30 minute bake karein, jab tak gehra sunehra aur kurkura na ho jaye.","5 minute rest dein, tin se nikaal lein, aur tomato sauce ke sath garam serve karein."],"tip":"Pastry bharne se pehle filling ko poori tarah thanda karein. Halki si garam filling bhi pastry ko naram kar deti hai aur oven mein kurkura hone se rokti hai.","notes":["Beef chuck halki aanch par pakane se naram aur rich ho jata hai. Lean stewing beef sookh jata hai, aur qeeme se mukhtalif, naram pie banti hai.","Vegemite namkeen, yeasty gehraai daalti hai jo pehchan mein mushkil lekin bila shuba Australian hai. Sirf thori use karein, warna filling par haawi ho jayegi.","Base ke liye shortcrust structure deti hai, lid ke liye puff pastry flake deti hai. Dono ke liye puff pastry use karne se base geela ho jata hai.","Ande ki wash sunehri chamak deti hai. Bake karne se pehle brush karein, aur steam hole mein jama na hone dein."],"variations":["Mushroom ke sath: piyaz ke sath kati hui mushroom daalein, extra zaiqe aur halki filling ke liye.","Chicken pie: wohi sauce ke sath chicken thigh use karein, 40 minute pakayein, chicken version ke liye.","Cheese aur bacon pie: bake karne se pehle thandi filling mein kaddukas cheese aur paka hua bacon daalein."],"serving":"6 logon ke liye hai, alag pie ke tor par, oven se garam, upar tomato sauce aur saath saada salad ya matar ke sath. Meat pie haath se khane wala khana hai, is liye platon par kaante ke sath serve karein, lekin garam hote hue haathon se khane ki hosla afzai karein. Lunch, picnic aur sport dekhne ke liye behtareen hain, table par extra tomato sauce ke sath.","storage":"Paki hui pie fridge mein dhak kar 3 din tak rehti hai, aur 180C par oven mein garam aur kurkura hone tak dobara garam hoti hai, taqreeban 15 minute. 3 mahine tak achhi tarah freeze hoti hai, paki hui ya kachhi, fridge mein raat bhar rakh kar thaw karein. Sirf filling fridge mein 3 din aur freezer mein 3 mahine tak rehti hai. Kurkuri crust chahiye to pie ko microwave na karein.","mistakes":["Pastry ko garam rehte hue bharna. Pastry pighal jati hai aur geeli ho jati hai, is liye filling ko poori tarah thanda karein.","Base ko kam bake karna. Neeche pheeka aur naram rehta hai, is liye lid ke gehra sunehra hone aur base ke set hone tak bake karein.","Steam hole bhool jana. Steam jama ho kar lid ko phaar deta hai, is liye har pie mein chhota hole kaatein.","Filling ko zyada patla banana. Kaatne par beh jati hai, is liye chamach par mound banne tak simmer karein."],"faq":[["Kya dukaan ki pastry use kar sakta hoon?","Ji haan. Achhi quality wali shortcrust aur puff pastry achhi chalti hain, aur bohat waqt bachati hain. Use karne tak thanda rakhein."],["Kya aik bari pie bana sakta hoon?","Ji haan. 20cm pie dish use karein, shortcrust se line karein, bharein, puff pastry se dhak dein, aur 40 se 45 minute bake karein."],["Vegemite kis liye hai?","Ye filling mein namkeen, yeasty gehraai daalti hai. Na mile to thori extra Worcestershire sauce aur chutki bhar namak use karein."],["Kya meat pie freeze kar sakta hoon?","Ji haan, paki hui ya kachhi, 3 mahine tak. Frozen se bake karein, 10 se 15 minute aur daal kar, jab tak garam na ho jaye."]]}};
